INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('古典物理學', '古典物理學', '古典物理學是十七至十九世紀發展的物理學體系，涵蓋力學、熱學、光學和電磁學四大分支，在日常尺度下準確描述自然現象。', ARRAY['物理學的發展']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('長度單位', '長度單位', '常用長度單位包含 km/cm/mm/μm/nm，天文用光年(9.46×10¹⁵m)，原子尺度用埃(10⁻¹⁰m)和費米(10⁻¹⁵m)。', ARRAY['長度標準']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('地心說', '地心說', '地心說認為地球是宇宙的中心，太陽、月亮和行星都繞著地球轉動，由托勒密於約西元二世紀建立。', ARRAY['自然哲學與四元論']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('質量', '質量', '質量是物質含有量的量度，不隨位置改變，國際標準為保存於巴黎的鉑銥合金公斤原器。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('物理量的數與量', '物理量的數與量', '物理量由「數值」和「單位」兩部分組成，缺一不可。例如 3.5 公尺中，3.5 是數值，公尺是單位。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('單位前綴', '單位前綴', 'SI 制使用標準前綴表示不同量級，從 atto(10⁻¹⁸) 到 tera(10¹²)，常用有 nano/micro/milli/kilo/mega/giga。', ARRAY['國際單位系統']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('絕對誤差與百分誤差', '絕對誤差與百分誤差', '絕對誤差 ΔA = A - A₀，百分誤差 = |ΔA|/A₀ × 100%，用於量化測量的準確程度。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('隨機誤差', '隨機誤差', '隨機誤差由偶然因素（振動、氣流、個人差異）造成，沒有固定偏向，可透過增加測量次數來降低。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('積體電路', '積體電路', '積體電路（IC, Integrated Circuit）是將完整的電子電路整合在一個半導體晶片上的技術，1958 年發明，使電子產品走向輕薄短小。', ARRAY['半導體']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('量子論', '量子論', '量子論是卜朗克於 1900 年提出的革命性理論：能量不是連續的，而是以一份一份的「量子」為最小單位。', ARRAY['古典物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('光纖通訊', '光纖通訊', '光纖通訊利用石英（玻璃）纖維中的全反射現象來傳輸光訊號，具有容量大、長距離、不受電磁干擾、輕巧等優點。', ARRAY['全反射']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('萬有引力定律', '萬有引力定律', '任何兩個物體之間都存在引力，引力大小與兩物體質量的乘積成正比，與它們之間距離的平方成反比。', ARRAY['行星運動三大定律']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('半衰期', '半衰期', '半衰期是放射性元素衰變至原來一半所需的時間，不受外界條件影響，碳-14 的半衰期約 6000 年。', ARRAY['放射性']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('核能發電', '核能發電', '核能發電利用鈾-235 的受控核分裂連鎖反應產生熱能，再轉換為電能，其能量來源是愛因斯坦的質能互換 E = mc²。', ARRAY['核分裂與核融合','質能互換公式']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('光的波粒二象性', '光的波粒二象性', '光同時具有波動性（干涉、繞射）和粒子性（光電效應），這種雙重性質稱為波粒二象性。', ARRAY['光的粒子說與波動說','光電效應']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('螺旋測微器', '螺旋測微器', '螺旋測微器利用螺旋原理放大微小位移，螺距 0.5mm、50 刻度，精密度 0.01mm，測量值可達 0.001mm。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('原子模型演進', '原子模型演進', '原子模型經歷了三個重要階段：湯木生的葡萄乾布丁模型→拉塞福的行星式模型→波耳的量子化軌道模型。', ARRAY['量子論']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('電磁波', '電磁波', '電磁波是電場和磁場交互振盪在空間中傳播的波動，由馬克士威從理論預測，赫茲以實驗驗證，光是電磁波的一種。', ARRAY['電磁感應']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('近代物理學', '近代物理學', '近代物理學是二十世紀發展的物理學，以量子力學和相對論為兩大支柱，揭示了微觀世界和高速運動的新規律。', ARRAY['古典物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('強作用力', '強作用力', '強作用力是將質子和中子束縛在原子核中的力，是自然界四種基本力中最強的一種，由海森伯提出、湯川秀樹建立介子場論描述。', ARRAY['原子模型演進']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('核分裂與核融合', '核分裂與核融合', '核分裂是重原子核分裂為較輕原子核，核融合是輕原子核合併為較重原子核，兩者都能釋放巨大能量（E = mc²）。', ARRAY['相對論','放射性']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('太陽日與恆星日', '太陽日與恆星日', '太陽日是太陽連續兩次通過子午線的時間間隔，恆星日是地球自轉一周的真正週期，太陽日比恆星日長。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('電磁感應', '電磁感應', '電磁感應是變化的磁場在導體中產生感應電流的現象，由法拉第於 1831 年發現，是發電機的基本原理。', ARRAY['古典物理學','電磁波']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('因次定理', '因次定理', '因次定理用基本量（M、L、T 等）表示導出量的維度，例如速度的因次為 LT⁻¹，力的因次為 MLT⁻²。', ARRAY['SI七大基本量']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('光電效應', '光電效應', '光電效應是光照射金屬表面時，金屬會釋出電子的現象。愛因斯坦用光子論成功解釋，獲 1921 年諾貝爾物理獎。', ARRAY['量子論']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('超導體', '超導體', '超導體是在冷卻到轉變溫度以下時電阻完全消失的材料，由乃內斯於 1911 年發現，具有零電阻和反磁性兩大特性。', ARRAY['近代物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('光的粒子說與波動說', '光的粒子說與波動說', '光的本質是物理學史上持續最久的爭論之一：牛頓認為光是粒子流，海更士認為光是波動，最終愛因斯坦揭示光兼具兩種性質。', ARRAY['古典物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('三角測量法', '三角測量法', '三角測量法利用已知基線長度和兩端角度，通過三角函數計算無法直接測量的距離。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('數量級', '數量級', '數量級用 10 的冪次估計數值大小，判斷規則：a < √10 取 10ⁿ，a ≥ √10 取 10ⁿ⁺¹。', ARRAY['科學記號']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('日心說', '日心說', '日心說認為太陽是宇宙的中心，地球和其他行星繞太陽公轉並自轉，由哥白尼於 1543 年提出。', ARRAY['地心說']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('科學記號', '科學記號', '科學記號 X = a × 10ⁿ（1 ≤ a < 10）是表示極大或極小數值的標準方法。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('有效數字運算法則', '有效數字運算法則', '加減法結果取到一位估計值，乘除法結果取最少有效位數，開方取與原量相同位數。', ARRAY['有效數字']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('時間標準', '時間標準', '1967 年定義：銫-133 原子在基態兩個超精細能級之間躍遷時所發射的光振動 9,192,631,770 次為 1 秒。', ARRAY['國際單位系統']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('有效數字', '有效數字', '有效數字是測量值中有意義的數字位數，反映了測量的精密程度。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('相對論', '相對論', '相對論是愛因斯坦提出的時空理論：狹義相對論（1905）揭示時間膨脹和質能互換，廣義相對論（1915）將重力解釋為時空彎曲。', ARRAY['古典物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('SI七大基本量', 'SI七大基本量', 'SI 制的七大基本量：長度(m)、質量(kg)、時間(s)、發光強度(cd)、溫度(K)、電流(A)、物質計量(mol)。', ARRAY['國際單位系統']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('天文學革命', '天文學革命', '天文學革命是十六至十七世紀從地心說到日心說的典範轉移，由哥白尼發起、經第谷觀測、克卜勒定律、伽利略觀測，最終由牛頓的萬有引力定律完成。', ARRAY['地心說','日心說']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('雷射', '雷射', '雷射（LASER = Light Amplification by Stimulated Emission of Radiation）是利用受激輻射原理產生的特殊光源，具有準直、高強度、不發散、可精確聚焦等特性。', ARRAY['量子論']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('游標尺', '游標尺', '游標尺由主尺和副尺組成，副尺 n+1 格對齊主尺 n mm，精密度為 1/(n+1) mm。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('半導體', '半導體', '半導體是導電能力介於導體和絕緣體之間的材料（如矽、砷化鎵），其導電性可通過摻雜或施加電壓來控制，是現代電子工業的基礎。', ARRAY['近代物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('系統誤差', '系統誤差', '系統誤差由儀器校正不良、公式不正確或人為操作不當造成，具有固定偏向性，可透過正確操作降低。', ARRAY['測量值與誤差']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('慣性', '慣性', '慣性是物體在不受外力作用時，保持靜止或等速直線運動狀態的性質，由伽利略的斜面實驗首次揭示。', ARRAY['天文學革命']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('自然哲學與四元論', '自然哲學與四元論', '古希臘的自然哲學認為世間萬物由火、水、土、氣四種元素組成，是人類最早嘗試系統化理解自然的思想體系。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('全反射', '全反射', '全反射是光從光密介質（高折射率）射入光疏介質（低折射率）時，當入射角大於臨界角，光完全被反射回原介質的現象。', ARRAY['光的粒子說與波動說']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('國際單位系統', '國際單位系統', 'SI（Systeme International）是 1960 年巴黎會議確立的國際單位制度，具備恆常性、複製性和國際公認三大特徵。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('行星運動三大定律', '行星運動三大定律', '克卜勒從第谷的觀測數據中歸納出的三條數學定律，精確描述行星繞太陽運動的軌道、速度和週期。', ARRAY['日心說']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('放射性', '放射性', '放射性是某些不穩定原子核自發地放出射線（α、β、γ）的現象，由侖琴的 X 光發現引發，經貝克勒和居里夫婦深入研究。', ARRAY['原子模型演進','近代物理學']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('長度標準', '長度標準', '長度標準經歷四次演變：子午線(1792)→鉑銥合金(1889)→氪86光波(1960)→光速定義(1983)。', ARRAY['國際單位系統']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('夸克理論', '夸克理論', '夸克理論由蓋耳曼於 1963 年提出：質子和中子不是基本粒子，而是由更基本的「夸克」組成，每個質子或中子由三個夸克構成。', ARRAY['原子模型演進']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('測量值與誤差', '測量值與誤差', '測量值由「準確值」加上「一位估計值」組成，最小刻度對應倒數第二位數字。任何測量都有誤差。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('物理學的發展', '物理學的發展', '物理學（Physics）源自希臘文「自然」，是研究自然界基本規律的科學，從自然哲學演變為以實驗為基礎的精確科學。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('單擺', '單擺', '單擺是擺長約 1 公尺、擺角在 5° 以內的簡單擺動系統，具有等時性，週期 T = 2π√(L/g)。', ARRAY[]::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('雷射應用', '雷射應用', '雷射的準直性、高強度和可聚焦特性，使其在醫學、工業、軍事和日常生活中有廣泛應用。', ARRAY['雷射','量子論']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('半導體與電子工業', '半導體與電子工業', '半導體技術從矽晶體出發，經電晶體、積體電路到 CPU，使電子產品走向輕薄短小。', ARRAY['半導體','積體電路']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('核能發電應用', '核能發電應用', '核能發電利用鈾-235 的受控核分裂連鎖反應加熱水產生蒸汽推動渦輪發電。', ARRAY['核能發電','核分裂與核融合']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('超導體應用', '超導體應用', '超導體的零電阻和反磁性（麥士納效應）使其在磁浮列車、MRI 和電力傳輸等領域有重要應用潛力。', ARRAY['超導體']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
INSERT INTO public.concepts (id, name, description, prerequisites) VALUES ('光纖通訊應用', '光纖通訊應用', '石英光纖利用全反射原理傳輸光訊號，具有容量大、距離長、不受電磁干擾等優點。', ARRAY['全反射','光纖通訊']::TEXT[]) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, prerequisites = EXCLUDED.prerequisites;
