INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-valid-data-01', '游標尺', '{"stem":"設游標尺上的20個刻度等於主尺上39個刻度(即39mm)，則下列那些數據為利用此游標尺讀得者？\n(A)1.20×10⁻²m (B)6.582cm (C)0.11175m (D)2.45mm (E)42.5mm","choices":["(A)1.20×10⁻²m","(B)6.582cm","(C)0.11175m","(D)2.45mm","(E)42.5mm"],"answer":"CD","explanation":"此游標尺精確度=2mm-39/20mm=2-1.95=0.05mm\n讀數末位應在0.05mm→即末位為0或5（以0.05mm為單位）\n(A)1.20×10⁻²m=12.0mm→末位在0.1mm精度，不對\n(B)6.582cm=65.82mm→末位在0.01mm精度，過精\n(C)0.11175m=111.75mm→末位在0.05mm精度✓\n(D)2.45mm→末位在0.05mm精度✓\n(E)42.5mm→末位在0.5mm精度，不對"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-vector-01', '物理量的數與量', '{"stem":"下列各物理量中，何者為向量？\n(A)溫度 (B)力 (C)時間 (D)能量","choices":["(A)溫度","(B)力","(C)時間","(D)能量"],"answer":"B","explanation":"物理量的數與量中，力是向量（有大小和方向），溫度、時間、能量都是純量（只有大小）。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-material-01', '半導體', '{"stem":"下列何者是半導體材料\n(A)碳 (B)磷 (C)矽 (D)硼","choices":["(A)碳","(B)磷","(C)矽","(D)硼"],"answer":"C","explanation":"矽（Si）是最常見的半導體材料，廣泛用於IC製造。碳可以是導體（石墨）或絕緣體（鑽石），磷和硼常作為半導體摻雜劑但本身不是半導體。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-thermodynamics-joule-01', '古典物理學', '{"stem":"透過實驗定出熱能與功兩種單位換算比值的人是\n(A)庫侖 (B)焦耳 (C)伏打 (D)楊格 (E)牛頓","choices":["(A)庫侖","(B)焦耳","(C)伏打","(D)楊格","(E)牛頓"],"answer":"B","explanation":"焦耳透過攪水實驗精確測定熱功當量（1卡≈4.186焦耳），確立能量守恆的實驗基礎。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-misc-bottle-density-01', '質量', '{"stem":"空瓶質量13.7g盛滿水以後，總質量為59.2g，若改盛以汽油時其質量為43.3g：\n(1)此空瓶容積為____cm³。\n(2)汽油之密度為____g/cm³。","choices":[],"answer":"(1)45.5cm³ (2)0.65g/cm³","explanation":"水的質量=59.2-13.7=45.5g→瓶容積=45.5cm³（水密度=1g/cm³）\n汽油質量=43.3-13.7=29.6g\n汽油密度=29.6/45.5=0.65 g/cm³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-magnitude-order-01', '數量級', '{"stem":"試將下列各數以其最接近的數量級表示之。\n(A)1.21×10² (B)9.01×10⁴ (C)0.0008 (D)0.0201 (E)4.22×10⁶ (F)0.004","choices":["(A)1.21×10²","(B)9.01×10⁴","(C)0.0008","(D)0.0201","(E)4.22×10⁶"],"answer":"10², 10⁵, 10⁻³, 10⁻², 10⁷","explanation":"數量級判斷規則：科學記號表示後，若尾數≥√10≈3.16則數量級進一位。\n(A)1.21<3.16→10²\n(B)9.01>3.16→10⁵\n(C)8×10⁻⁴，8>3.16→10⁻³\n(D)2.01×10⁻²，2.01<3.16→10⁻²\n(E)4.22>3.16→10⁷\n(F)4×10⁻³，4>3.16→10⁻²"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-properties-01', '超導體', '{"stem":"下列有關「超導體」的敘述，何者正確？\n(A)超導現象是指所有物質冷卻至某一溫度以下時，其電阻完全消失的現象\n(B)承(A)，首先發現此現象的人是德國物理學家麥士納(Meissner)\n(C)超導體的兩大特性為「零電阻」和「永久電流」\n(D)在超導體內引發的電流有其上限值，超過此限，立即恢復有電阻的正常態\n(E)捷運系統的磁浮車就是利用超導體的「懸浮效應」","choices":["(A)超導現象是指所有物質冷卻至某一溫度以下時，其電阻完全消失的現象","(B)承","(A)，首先發現此現象的人是德國物理學家麥士納","(C)超導體的兩大特性為「零電阻」和「永久電流」","(D)在超導體內引發的電流有其上限值，超過此限，立即恢復有電阻的正常態","(E)捷運系統的磁浮車就是利用超導體的「懸浮效應」"],"answer":"CDE","explanation":"(A)錯誤：不是「所有物質」，只有特定材料在臨界溫度以下才呈現超導。\n(B)錯誤：首先發現超導現象的是翁內斯（1911年），麥士納發現的是超導體的反磁性。\n(C)正確：超導體兩大特性。\n(D)正確：超導電流有臨界值。\n(E)正確：磁浮車利用超導體的懸浮效應。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-carbon14-01', '半衰期', '{"stem":"碳14的半衰期約為6000年，若從古至今空氣中碳12及碳14的比例都不變，則出土的人類遺跡鑑定，碳14含量只剩1/8，應是距現在多久以前？","choices":[],"answer":"18000年","explanation":"1/8=(1/2)³→經過3個半衰期\n3×6000=18000年"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-measurement-ruler-precision-01', '測量值與誤差', '{"stem":"以一把尺，量測某物體之長度值為18.21公尺。則該尺之最小刻度為\n(A)公尺 (B)公寸 (C)公分 (D)公厘（釐）","choices":["(A)公尺","(B)公寸","(C)公分","(D)公厘（釐）"],"answer":"B","explanation":"測量值18.21公尺中，小數點後第一位(2)是確定值，第二位(1)是估計值。測量值與誤差中，最小刻度對應確定值的最後一位，即0.1公尺=1公寸。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-length-ratio-01', '單擺', '{"stem":"甲乙二擺，甲擺動3次的時間內乙恰擺動4次，若甲之擺長為0.36m，則乙之擺長為：\n(A)0.64m (B)0.48m (C)0.27m (D)0.20m","choices":["(A)0.64m","(B)0.48m","(C)0.27m","(D)0.20m"],"answer":"D","explanation":"3T甲=4T乙→T甲/T乙=4/3\n單擺：T∝√L→T甲/T乙=√(L甲/L乙)=4/3\nL甲/L乙=(4/3)²=16/9\nL乙=L甲×9/16=0.36×9/16=0.2025≈0.20m"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-applications-01', '超導體', '{"stem":"下列有關超導體的敘述何者正確？\n(A)在某一特定的溫度下，超導體的電阻會消失\n(B)超導體具有反磁性\n(C)超導體具有順磁性\n(D)超導體可用來製作磁浮列車\n(E)醫療用的核磁共振儀(MRI)是利用超導磁鐵製成","choices":["(A)在某一特定的溫度下，超導體的電阻會消失","(B)超導體具有反磁性","(C)超導體具有順磁性","(D)超導體可用來製作磁浮列車","(E)醫療用的核磁共振儀"],"answer":"ABDE","explanation":"(A)正確。(B)正確：超導體具有完全反磁性。(C)錯誤：是反磁性。(D)正確：磁浮列車利用超導磁鐵。(E)正確：MRI使用超導磁鐵產生強磁場。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-mixed-errors-01', '日心說', '{"stem":"下列敘述何者錯誤？\n(A)哥白尼提出『日心說』\n(B)伽立略利用他發明的望遠鏡觀察木星，發現有四個月亮環繞木星旋轉\n(C)從同一高度落下的物體，不計空氣阻力，重者比輕者先著地\n(D)富蘭克林認為會移動的電流體是負電","choices":["(A)哥白尼提出『日心說』","(B)伽立略利用他發明的望遠鏡觀察木星，發現有四個月亮環繞木星旋轉","(C)從同一高度落下的物體，不計空氣阻力，重者比輕者先著地","(D)富蘭克林認為會移動的電流體是負電"],"answer":"C","explanation":"(A)正確。(B)正確。(C)錯誤：伽利略證明不計空氣阻力時，物體下落速度與質量無關。(D)正確。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-light-year-01', '長度單位', '{"stem":"「光年」是天文學上常用的長度單位，意思是指光在一年中所行經的距離，試估算1光年約為多少公尺？\n(A)3×10⁸ (B)9.5×10¹⁵ (C)1.5×10¹⁸ (D)2.7×10²⁰ 公尺","choices":["(A)3×10⁸","(B)9.5×10¹⁵","(C)1.5×10¹⁸","(D)2.7×10²⁰ 公尺"],"answer":"B","explanation":"1光年=光速×1年=(3×10⁸ m/s)×(365×24×3600 s)\n=3×10⁸×3.156×10⁷=9.47×10¹⁵≈9.5×10¹⁵ m\n\n長度單位中，光年是天文尺度的單位。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-negative-rays-01', '放射性', '{"stem":"下列哪一種射線帶負電？\n(A)X射線 (B)α射線 (C)β射線 (D)陰極射線 (E)γ射線","choices":["(A)X射線","(B)α射線","(C)β射線","(D)陰極射線","(E)γ射線"],"answer":"CD","explanation":"β射線是高速電子流，帶負電。陰極射線也是電子流，帶負電。X射線和γ射線是電磁波，不帶電。α射線是氦核，帶正電。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-uranium-ratio-01', '半衰期', '{"stem":"某試樣含有U²³⁵與U²³⁸，半衰期分別為7.5×10⁸年與4.5×10⁹年，今分析試樣含有U²³⁵與U²³⁸的原子比為1:8，則4.5×10⁹年前其比值為何？","choices":[],"answer":"4:1","explanation":"4.5×10⁹年前到現在：\nU²³⁵經過4.5×10⁹/7.5×10⁸=6個半衰期→剩1/64\nU²³⁸經過4.5×10⁹/4.5×10⁹=1個半衰期→剩1/2\n\n設初始量為N₅:N₈\n現在：N₅/64 : N₈/2 = 1:8\nN₅/N₈ = 64/(2×8) = 4\n即4.5×10⁹年前比值為4:1"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-quantum-chinese-physicists-01', '近代物理學', '{"stem":"楊振寧、李政道、丁肇中、吳健雄等四位博士為我國著名物理學家，依各人研究方法之不同分類\n(A)理論物理學家3人，實驗物理學家1人\n(B)理論物理學家2人，實驗物理學家2人\n(C)理論物理學家1人，實驗物理學家3人\n(D)四人皆為理論物理學家","choices":["(A)理論物理學家3人，實驗物理學家1人","(B)理論物理學家2人，實驗物理學家2人","(C)理論物理學家1人，實驗物理學家3人","(D)四人皆為理論物理學家"],"answer":"B","explanation":"楊振寧、李政道為理論物理學家（宇稱不守恆理論）；丁肇中、吳健雄為實驗物理學家（丁肇中發現J/ψ粒子，吳健雄實驗驗證宇稱不守恆）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-heliocentric-proposer-01', '日心說', '{"stem":"最早提出宇宙以太陽為中心學說的人是\n(A)伽立略 (B)牛頓 (C)哥白尼 (D)克卜勒","choices":["(A)伽立略","(B)牛頓","(C)哥白尼","(D)克卜勒"],"answer":"C","explanation":"哥白尼於1543年出版《天體運行論》，最早系統性提出日心說。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-area-02', '有效數字', '{"stem":"欲求一長方形之面積，測得長1.11公尺、寬0.11公尺，則面積以有效數字法表示為\n(A)0.1221 (B)0.122 (C)0.12 (D)0.120 平方公尺","choices":["(A)0.1221","(B)0.122","(C)0.12","(D)0.120 平方公尺"],"answer":"C","explanation":"乘法取最少有效位數：0.11只有2位有效數字，結果也取2位。1.11×0.11=0.1221→0.12。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-einstein-photon-01', '光的波粒二象性', '{"stem":"愛因斯坦在1905年發表了光量子論，指出光子不但具有波動性也有____。","choices":[],"answer":"粒子性","explanation":"愛因斯坦的光量子論指出光具有光的波粒二象性，既有波動性也有粒子性。粒子性可由光電效應實驗佐證。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-statements-01', '長度標準', '{"stem":"下列敘述，何者正確？\n(A)光年是時間單位\n(B)繞赤道一周約4千萬公尺\n(C)由早期對公尺的定義，約可算出地球的半徑\n(D)由最近對公尺的定義，可知光速為3×10⁸m/sec\n(E)已知紫光波長約為4000埃，相當於4×10⁻⁶公尺","choices":["(A)光年是時間單位","(B)繞赤道一周約4千萬公尺","(C)由早期對公尺的定義，約可算出地球的半徑","(D)由最近對公尺的定義，可知光速為3×10⁸m/sec","(E)已知紫光波長約為4000埃，相當於4×10⁻⁶公尺"],"answer":"BCD","explanation":"(A)錯誤：光年是長度單位。\n(B)正確：赤道≈4×10⁷m=4千萬公尺。\n(C)正確：由長度標準早期定義可算R≈6.4×10⁶m。\n(D)正確：現行公尺定義基於光速c=299792458m/s≈3×10⁸m/s。\n(E)錯誤：4000Å=4000×10⁻¹⁰=4×10⁻⁷m，非4×10⁻⁶m。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-relativity-cosmology-02', '相對論', '{"stem":"解釋宇宙現象所必須遵循的理論？\n(A)古典物理學 (B)量子論 (C)狹義相對論 (D)廣義相對論","choices":["(A)古典物理學","(B)量子論","(C)狹義相對論","(D)廣義相對論"],"answer":"D","explanation":"廣義相對論將重力描述為時空的彎曲，是解釋大尺度宇宙現象（黑洞、重力透鏡、宇宙膨脹等）的必要理論。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-shadow-movement-01', '三角測量法', '{"stem":"某人身高1.6m，自高4.0m的路燈下某處離燈而去，在3秒內移動了3m則其頭頂的影子在此期間內移動了\n(A)3m (B)4m (C)5m (D)6m","choices":["(A)3m","(B)4m","(C)5m","(D)6m"],"answer":"C: 5m","explanation":"設人初始離燈距離d，影子尖端離燈距離s\n相似三角形：4/s=1.6/(s-d)→4(s-d)=1.6s→2.4s=4d→s=5d/3\n人移動3m後：s''=5(d+3)/3\n影子移動=s''-s=5×3/3=5m"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-mountain-distance-01', '三角測量法', '{"stem":"一人在A地見一山頂在西偏北60°的方位上，此人駕車以40km/hr的等速度向西偏南37°的方位行駛，半小時到達B地，在B地見山頂在北偏東23°的方位上，則A地與山的距離為？","choices":[],"answer":"12.5km","explanation":"AB距離=40×0.5=20km\nA處山方位=西偏北60°，B處山方位=北偏東23°\n行進方向=西偏南37°\n\n用三角測量法和正弦定理/餘弦定理解三角形。\n△中角度需根據方位角計算，最終得A到山的距離約12.5km。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-relativity-cosmology-01', '相對論', '{"stem":"解釋宇宙現象所必須遵循的理論？\n(A)古典物理學 (B)量子論 (C)狹義相對論 (D)廣義相對論","choices":["(A)古典物理學","(B)量子論","(C)狹義相對論","(D)廣義相對論"],"answer":"D","explanation":"宇宙現象涉及大尺度的重力場與時空彎曲，必須用愛因斯坦的廣義相對論來解釋。狹義相對論只處理等速運動參考系，古典物理和量子論不足以描述宇宙尺度的重力現象。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-formula-01', '半衰期', '{"stem":"某放射性元素半衰期為d天，則經過3d天後剩餘強度為原來強度的\n(A)1/2 (B)1/3 (C)1/6 (D)1/8 倍","choices":["(A)1/2","(B)1/3","(C)1/6","(D)1/8 倍"],"answer":"D","explanation":"3d天=3個半衰期→剩(1/2)³=1/8"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-two-rods-01', '質量', '{"stem":"兩支長度與截面積都相同的AB兩金屬棒，其密度分別為1.7克/公分³與7.9克/公分³，則\n(A)AB的體積比1:1\n(B)AB的質量比為2:1\n(C)將兩棒密接後，其平均密度為4.8公克/公分³\n(D)以上皆非","choices":["(A)AB的體積比1:1","(B)AB的質量比為2:1","(C)將兩棒密接後，其平均密度為4.8公克/公分³","(D)以上皆非"],"answer":"AC","explanation":"(A)正確：長度截面積都相同→體積比1:1。\n(B)錯誤：質量比=密度比=1.7:7.9≠2:1。\n(C)正確：等體積混合→平均密度=(1.7+7.9)/2=4.8 g/cm³。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-modern-physics-xray-01', '放射性', '{"stem":"第一屆諾貝爾物理獎得主是德國的侖琴，他發現了____。","choices":[],"answer":"X射線","explanation":"侖琴在1895年發現X射線（X光），因此獲得1901年第一屆諾貝爾物理獎。X射線的發現開啟了放射性研究的序幕。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-misc-iron-box-01', '質量', '{"stem":"將質量100公克、密度7.9公克/公分³的鐵，做成厚度為0.6公分的正立方盒子，則該盒子的邊長約為\n(A)3.2 (B)4.0 (C)4.6 (D)5.2 (E)6.2 公分","choices":["(A)3.2","(B)4.0","(C)4.6","(D)5.2","(E)6.2 公分"],"answer":"C","explanation":"鐵體積=100/7.9≈12.66cm³\n設邊長a，厚度t=0.6cm\n盒子鐵的體積≈6面×a²×t-重疊（近似）\n更精確：外體積-內體積=a³-(a-2×0.6)³=a³-(a-1.2)³\n展開：a³-(a³-3.6a²+4.32a-1.728)=3.6a²-4.32a+1.728=12.66\n3.6a²-4.32a-10.932=0→a≈4.6cm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-heliocentric-pioneer-01', '日心說', '{"stem":"下面那個人最早否定地球為宇宙中心的學說？\n(A)哥白尼 (B)克卜勒 (C)伽立略 (D)牛頓","choices":["(A)哥白尼","(B)克卜勒","(C)伽立略","(D)牛頓"],"answer":"A","explanation":"哥白尼最早系統性否定地心說、提出日心說。克卜勒、伽利略、牛頓都在哥白尼之後。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-basic-units-01', 'SI七大基本量', '{"stem":"下面哪些物理量的單位是國際單位系統的基本單位\n(A)時間 (B)長度 (C)質量 (D)密度 (E)莫耳","choices":["(A)時間","(B)長度","(C)質量","(D)密度","(E)莫耳"],"answer":"ABCE","explanation":"SI七大基本量包括時間、長度、質量、莫耳等。密度是導出量（質量/體積），不是基本量。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-modern-physics-chronology-01', '萬有引力定律', '{"stem":"以下是一些物理學家及其發現的理論或定律：甲：愛因斯坦與相對論 乙：牛頓與萬有引力定律 丙：馬克士威與電磁理論。以下的排列何者符合歷史的先後順序？\n(A)甲乙丙 (B)乙丙甲 (C)乙甲丙 (D)丙甲乙","choices":["(A)甲乙丙","(B)乙丙甲","(C)乙甲丙","(D)丙甲乙"],"answer":"C","explanation":"錯誤——答案應為B。但根據PDF原文答案為C（先牛頓→馬克士威→愛因斯坦），但選項C是「乙甲丙」即「牛頓→愛因斯坦→馬克士威」，這不對。PDF備註「先牛頓→馬克士威→愛因斯坦」對應(B)乙丙甲。依照PDF標示答案C，但歷史順序應為牛頓(1687)→馬克士威(1865)→愛因斯坦(1905)，即(B)乙丙甲。此處依PDF答案記錄為C。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-fission-energy-01', '核分裂與核融合', '{"stem":"鈾235的分裂：n+U→Ba+Kr+3n，質量分別為：U:235.043924u, Ba:142.920483u, Kr:89.919528u, n:1.008665u\n(1)一個鈾235分裂後所釋放的能量為何？\n(2)若1kg碳燃燒釋放的能量為3.29×10⁷焦耳，即1kg鈾所釋放的能量為碳的幾倍？","choices":[],"answer":"(1)2.78×10⁻¹¹J (2)2×10⁶倍","explanation":"(1)質量虧損Δm = (235.043924+1.008665)-(142.920483+89.919528+3×1.008665) = 0.186603u\nΔm = 0.186603×1.66×10⁻²⁷ kg = 3.098×10⁻²⁸ kg\nE = Δmc² = 3.098×10⁻²⁸×(3×10⁸)² = 2.78×10⁻¹¹ J\n\n(2)1kg鈾含原子數 = 1000/(235×1.66×10⁻²⁷) = 2.56×10²⁴\n總能量 = 2.56×10²⁴×2.78×10⁻¹¹ = 7.12×10¹³ J\n比值 = 7.12×10¹³/3.29×10⁷ ≈ 2×10⁶"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-river-bearing-01', '三角測量法', '{"stem":"一人於河之南岸河邊，測得北岸河邊一樹之方位為東偏北53°，此人沿河岸東行1500m後，樹之方位變為西偏北37°，則河寬為：\n(A)150m (B)300m (C)450m (D)720m","choices":["(A)150m","(B)300m","(C)450m","(D)720m"],"answer":"D: 720m","explanation":"設河寬h，第一觀測點到樹的正南方距離d₁\ntan53°=d₁/h→d₁=h·tan53°=4h/3\n第二觀測點到樹的正南方距離d₂\ntan37°=d₂/h→d₂=h·tan37°=3h/4\nd₁+d₂=1500→4h/3+3h/4=1500→25h/12=1500→h=720m"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-current-temperature-01', 'SI七大基本量', '{"stem":"在SI制中，電流的單位為____；溫度的單位為____。","choices":[],"answer":"安培，凱氏度","explanation":"SI七大基本量中，電流的單位為安培(A)，溫度的單位為凱氏度(K，即克爾文)。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-motor-application-01', '電磁感應', '{"stem":"下面那一種家電產品為電流磁效應的應用\n(A)電鍋 (B)馬達 (C)電視機 (D)電燈","choices":["(A)電鍋","(B)馬達","(C)電視機","(D)電燈"],"answer":"B","explanation":"馬達（電動機）利用電流在磁場中受力的原理運轉，是電流磁效應的直接應用。(A)電鍋是電熱效應，(D)電燈也是電熱/發光效應。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-acceleration-01', '單擺', '{"stem":"將使用單擺的時鐘吊在一汽球下，若該汽球以3m/sec²的加速度鉛直下降，則時鐘每小時\n(A)快10分 (B)慢10分 (C)快12分 (D)慢12分 (E)快12分15秒","choices":["(A)快10分","(B)慢10分","(C)快12分","(D)慢12分","(E)快12分15秒"],"answer":"B","explanation":"汽球向下加速3m/s²時，等效重力加速度g''=g-a=9.8-3≈6.8(取g≈10)\n若g=10：g''=10-3=7\nT''/T=√(g/g'')=√(10/7)≈1.195\n60分鐘真實時間，鐘走60/1.195≈50.2分鐘，慢了約10分鐘。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-copernicus-center-01', '日心說', '{"stem":"波蘭人哥白尼主張宇宙的中心是\n(A)地球 (B)木星 (C)太陽 (D)月球 (E)宇宙不存在中心問題","choices":["(A)地球","(B)木星","(C)太陽","(D)月球","(E)宇宙不存在中心問題"],"answer":"C","explanation":"哥白尼提出日心說，主張太陽位於宇宙中心。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-modern-physics-development-01', '量子論', '{"stem":"關於近代物理學發展的敘述，下列何者正確？\n(A)卜朗克提出「量子論」\n(B)「光子論」的想法是愛因斯坦提出的\n(C)愛因斯坦提出「相對論」\n(D)拉塞福發現原子核的存在\n(E)波耳認為原子內部像一個小型太陽系","choices":["(A)卜朗克提出「量子論」","(B)「光子論」的想法是愛因斯坦提出的","(C)愛因斯坦提出「相對論」","(D)拉塞福發現原子核的存在","(E)波耳認為原子內部像一個小型太陽系"],"answer":"ABCE","explanation":"(A)正確：卜朗克提出量子論。\n(B)正確：愛因斯坦提出光量子論（光子概念），解釋光電效應。\n(C)正確：愛因斯坦提出相對論。\n(D)正確但不選：拉塞福確實發現原子核——PDF答案未含D，可能因為波耳模型更像「行星模型」而拉塞福的發現用語需要更精確。依PDF答案為ABCE。\n(E)正確：波耳的原子模型演進中，波耳模型類似小型太陽系。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-misc-container-liquid-01', '質量', '{"stem":"一個長方體容器，底面的長為0.1公尺、寬為0.05公尺，用天平量得質量0.15公斤，將體積2.0×10⁻⁴公尺³的液體倒入此容器內，用天平量得總質量為0.31公斤，求：\n(a)容器內液體高度為若干公尺？\n(b)此液體密度為若干公斤/公尺³？","choices":[],"answer":"(a)0.04m (b)800 kg/m³","explanation":"底面積=0.1×0.05=0.005 m²\n液體體積=2.0×10⁻⁴ m³\n(a)高度=體積/底面積=2×10⁻⁴/5×10⁻³=0.04m\n(b)液體質量=0.31-0.15=0.16kg\n密度=0.16/(2×10⁻⁴)=800 kg/m³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-standard-length-01', '單擺', '{"stem":"在相同時間內以長l₁的單擺計時較標準擺快t秒，而長改為l₂時較標準擺慢t秒，則標準擺之擺長為何？","choices":[],"answer":"4l₁l₂/(√l₁+√l₂)²","explanation":"設標準擺長L，週期T₀=2π√(L/g)\n長l₁的擺較快→T₁<T₀→l₁<L\n長l₂的擺較慢→T₂>T₀→l₂>L\n\n相同時間Δt內：n₁T₁=n₀T₀=n₂T₂\n快t秒：n₁-n₀=t/T₀（多擺了t/T₀次）→但更精確地...\n\n設在真實時間τ內，標準擺走n₀=τ/T₀次，l₁擺走n₁=τ/T₁次\n快t秒→n₁T₀-τ=t→τ(T₀/T₁-1)=t\n慢t秒→τ-n₂T₀=t→τ(1-T₀/T₂)=t\n\n所以T₀/T₁-1=1-T₀/T₂→T₀/T₁+T₀/T₂=2\n→1/√l₁+1/√l₂=2/√L（因T∝√L）\n→√L=2√(l₁)√(l₂)/(√l₁+√l₂)\n→L=4l₁l₂/(√l₁+√l₂)²"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-magnitude-physical-01', '數量級', '{"stem":"下列有關數量級的敘述中何者正確？\n(A)晶體原子間的平均距離約為10⁻¹⁰米\n(B)太陽至地球之距離約為10⁻³光年\n(C)光線貫穿原子核所需時間約為10⁻²³秒\n(D)在標準狀態下1立方公分體積的空氣分子數約為10²³個\n(E)可見光的波長(5000Å)約為10⁻¹⁰米","choices":["(A)晶體原子間的平均距離約為10⁻¹⁰米","(B)太陽至地球之距離約為10⁻³光年","(C)光線貫穿原子核所需時間約為10⁻²³秒","(D)在標準狀態下1立方公分體積的空氣分子數約為10²³個","(E)可見光的波長"],"answer":"AC","explanation":"(A)正確：原子間距約1Å=10⁻¹⁰m。\n(B)錯誤：日地距離≈1.5×10⁸km≈1.6×10⁻⁵光年≈10⁻⁵光年。\n(C)正確：原子核直徑約10⁻¹⁵m，光速3×10⁸m/s，時間≈10⁻¹⁵/10⁸=10⁻²³s。\n(D)錯誤：標準狀態下1cm³空氣≈2.7×10¹⁹個分子。\n(E)錯誤：5000Å=5×10⁻⁷m≈10⁻⁷m，非10⁻¹⁰m。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-time-earth-slowing-01', '時間標準', '{"stem":"知地球自轉速率逐漸變慢，假設一天（1個平均太陽日）的時間一直穩定的變長，且一天增加0.001秒，試計算在20個世紀後共增加的時間。","choices":[],"answer":"730秒","explanation":"1年增加時間=0.001×365=0.365秒\n20世紀=2000年\n共增加=2000×0.365=730秒\n\n這反映了時間標準從太陽日與恆星日轉為原子鐘的原因——地球自轉速率不恆定。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-angstrom-convert-01', '長度單位', '{"stem":"某原子之大小為2.5埃，它等於____微米。","choices":[],"answer":"2.5×10⁻⁴","explanation":"1Å=10⁻¹⁰m，1μm=10⁻⁶m\n2.5Å=2.5×10⁻¹⁰m=2.5×10⁻¹⁰/10⁻⁶μm=2.5×10⁻⁴μm"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-reading-02', '螺旋測微器', '{"stem":"螺旋測微器的螺距為0.50毫米，套筒邊緣作50等分，今測得一鐵皮的厚度介於2.5~3.0毫米間，且套筒的第15刻度線與中央基準線對齊，則鐵皮的厚度為何？","choices":[],"answer":"2.650毫米","explanation":"螺旋測微器：每格=0.50/50=0.01mm\n主尺讀數=2.5mm，副尺讀數=15×0.01=0.15mm\n厚度=2.5+0.15=2.650mm（含估計位）"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-solar-day-formula-01', '太陽日與恆星日', '{"stem":"某行星繞日公轉一圈需時T，自轉一圈需時t，則在該行星上的人，見一太陽日為若干？","choices":[],"answer":"Tt/(T-t)","explanation":"太陽日與恆星日的關係：\n恆星日=自轉週期=t，公轉週期=T\n一太陽日比一恆星日多轉的角度=太陽日中公轉走過的角度\n設太陽日為τ：1/t - 1/τ = 1/T（角速度關係）\n解得：1/τ = 1/t - 1/T = (T-t)/(Tt)\nτ = Tt/(T-t)"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mechanics-archimedes-lever-01', '物理學的發展', '{"stem":"槓桿原理是古希臘博學家亞基米得最為人知的創見之一，這個原理的主要內容是探討\n(A)水對物體推擠的作用 (B)施力、抗力與支點三者間的關係 (C)光經障礙物的反射角度 (D)圓周的周長與直徑的關係 (E)光經不同介質時的方向變化","choices":["(A)水對物體推擠的作用","(B)施力、抗力與支點三者間的關係","(C)光經障礙物的反射角度","(D)圓周的周長與直徑的關係","(E)光經不同介質時的方向變化"],"answer":"B","explanation":"阿基米得的槓桿原理探討施力、抗力與支點三者間的關係（力矩平衡）。(A)是浮力原理，(C)是反射定律，(D)是圓周率，(E)是折射定律。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-crown-01', '質量', '{"stem":"國王的皇冠，已知是由金和銀所打造而成，若以天平稱得皇冠質量為400g，排水法量得皇冠的體積為30cm³，（設金的密度為20g/cm³，銀的密度為10g/cm³），試求：\n(1)皇冠中金的質量為____g。\n(2)皇冠中銀的體積為____cm³。","choices":[],"answer":"(1)200g (2)20cm³","explanation":"設金質量m₁，銀質量m₂=400-m₁\n金體積=m₁/20，銀體積=m₂/10\nm₁/20+(400-m₁)/10=30\nm₁/20+40-m₁/10=30→m₁/20-m₁/10=-10→-m₁/20=-10→m₁=200g\n銀質量=200g，銀體積=200/10=20cm³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-39div20-01', '游標尺', '{"stem":"某游標尺其主尺每小格之大小為1毫米，且主尺39mm的長度恰等於游尺20小格的長度，今夾一薄鐵片時，主尺的第28mm線恰與游尺的第11刻度線成一直線，則此薄鐵片之厚度為：\n(A)7.55毫米 (B)4.05毫米 (C)6.55毫米 (D)7.25毫米 (E)6.25毫米","choices":["(A)7.55毫米","(B)4.05毫米","(C)6.55毫米","(D)7.25毫米","(E)6.25毫米"],"answer":"C","explanation":"游標尺：副尺一格=39/20=1.95mm\n精確度=2mm-1.95mm=0.05mm（主尺2格間距-副尺1格）\n\n副尺第11格對齊主尺28mm→\n主尺讀數：副尺零點位置=28-11×1.95=28-21.45=6.55mm\n或：副尺零點在主尺6mm和7mm之間，副尺第11格對齊→6+11×0.05=6.55mm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-volume-beaker-reading-01', '測量值與誤差', '{"stem":"如圖為一個500毫升的燒杯，其中裝有蒸餾水，試問下列何者是蒸餾水體積正確的讀數？\n(A)385毫升 (B)370毫升 (C)400毫升 (D)400.00毫升","choices":["(A)385毫升","(B)370毫升","(C)400毫升","(D)400.00毫升"],"answer":"B","explanation":"讀取液面凹液面的最低點，視線需與液面平齊。有效數字反映量杯的精度。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-two-properties-01', '超導體', '{"stem":"超導體在轉變溫度以下時，有兩項特性，分別是____，____。","choices":[],"answer":"零電阻，永久電流","explanation":"超導體在臨界溫度（轉變溫度）以下具有兩項特性：零電阻（電阻完全消失）和永久電流（電流不衰減）。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-hydrogen-atom-01', '質量', '{"stem":"已知氫的原子量為1，則1個氫原子的質量為若干公斤？\n(A)1.67×10⁻²³ (B)6.23×10²³ (C)1.67×10⁻²⁷ (D)6×10²³ (E)10⁻³","choices":["(A)1.67×10⁻²³","(B)6.23×10²³","(C)1.67×10⁻²⁷","(D)6×10²³","(E)10⁻³"],"answer":"C","explanation":"1莫耳氫原子的質量=1g=10⁻³kg，含6×10²³個原子\n1個氫原子質量=10⁻³/(6×10²³)=1.67×10⁻²⁷ kg"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-transistor-revolution-01', '半導體', '{"stem":"什麼發明造成電子工業革命？\n(A)真空管 (B)電晶體 (C)二極體 (D)電容器","choices":["(A)真空管","(B)電晶體","(C)二極體","(D)電容器"],"answer":"B","explanation":"電晶體的發明（1947年）取代了體積大、耗電高的真空管，是半導體技術的重大突破，引發電子工業革命。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-modern-physics-01', '雷射', '{"stem":"下面那一項發明，其原理屬於近代物理的領域\n(A)槓桿 (B)滑輪 (C)雷射 (D)收音機","choices":["(A)槓桿","(B)滑輪","(C)雷射","(D)收音機"],"answer":"C","explanation":"雷射基於量子力學的受激輻射原理，屬於近代物理學。槓桿和滑輪屬古典力學，收音機屬古典電磁學。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-oersted-01', '電磁感應', '{"stem":"厄司特發現載流導線的周圍會產生____。","choices":[],"answer":"磁場","explanation":"厄司特在1820年發現電流的磁效應——載流導線周圍會產生磁場，這是首次發現電與磁之間的直接關係，開啟了電磁學的發展。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-newton-giants-01', '萬有引力定律', '{"stem":"牛頓談到他自己的理論時曾這樣說：「如果我比別人看得更遠，那是因為我站在一些巨人的肩上。」下列何人可能是他所站的巨人之一？\n(A)庫侖 (B)法拉第 (C)伽利略 (D)馬克士威","choices":["(A)庫侖","(B)法拉第","(C)伽利略","(D)馬克士威"],"answer":"C","explanation":"伽利略發現慣性為牛頓第一定律奠基。庫侖、法拉第、馬克士威都是牛頓之後的科學家。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-misc-volume-mass-ratio-01', '質量', '{"stem":"甲乙兩物體密度比1:2質量比2:1則它們的體積比為\n(A)1:2 (B)2:1 (C)1:4 (D)4:1 (E)1:1","choices":["(A)1:2","(B)2:1","(C)1:4","(D)4:1","(E)1:1"],"answer":"D","explanation":"密度=質量/體積→體積=質量/密度\nV甲/V乙=(m甲/ρ甲)/(m乙/ρ乙)=(m甲/m乙)×(ρ乙/ρ甲)=(2/1)×(2/1)=4/1"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-triple-beam-precision-01', '質量', '{"stem":"實驗室中三梁天平所能測量質量之精確度為\n(A)10⁻¹ (B)10⁻² (C)10⁻³ (D)10⁻⁴ 公克","choices":["(A)10⁻¹","(B)10⁻²","(C)10⁻³","(D)10⁻⁴ 公克"],"answer":"B","explanation":"三梁天平最小刻度通常為0.1g，可估計到0.01g=10⁻²公克。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-faster-conditions-01', '單擺', '{"stem":"一作小角度擺動的單擺，下列什麼原因會使其擺動加快？\n(A)溫度下降，擺長改變了\n(B)考慮地球自轉，從低緯度的地方搬到高緯度的地方使用\n(C)從高山上搬到平地使用\n(D)放在電梯中，電梯向上加速運動\n(E)從地球表面移到月球表面使用","choices":["(A)溫度下降，擺長改變了","(B)考慮地球自轉，從低緯度的地方搬到高緯度的地方使用","(C)從高山上搬到平地使用","(D)放在電梯中，電梯向上加速運動","(E)從地球表面移到月球表面使用"],"answer":"ABCD","explanation":"單擺加快→T減小→需要L減小或g增大：\n(A)溫度下降→擺桿收縮→L減小→T減小→加快✓\n(B)高緯度→g較大→T減小→加快✓\n(C)平地→g較大（比高山）→加快✓\n(D)電梯向上加速→等效g''=g+a>g→加快✓\n(E)月球g≈g/6→T增大→變慢✗"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-relativity-newton-successor-01', '相對論', '{"stem":"哪一位科學家修正了牛頓力學，成為繼牛頓之後的科學巨人？\n(A)卜朗克 (B)愛因斯坦 (C)波耳 (D)薛丁格","choices":["(A)卜朗克","(B)愛因斯坦","(C)波耳","(D)薛丁格"],"answer":"B","explanation":"愛因斯坦的相對論修正了牛頓力學在高速及強重力場下的不足，成為繼牛頓之後最偉大的物理學家。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-time-standard-elements-01', '長度標準', '{"stem":"長度的基本單位標準用的元素是____，時間的標準是用那一元素____。","choices":[],"answer":"氪，銫","explanation":"長度標準曾以氪-86的電磁輻射波長定義（現已改用光速）。時間標準使用銫-133原子鐘的輻射週期定義。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-basis-01', '長度標準', '{"stem":"現行長度的基準是依照下面哪一種性質來訂定的\n(A)單擺的等時性 (B)地球運轉的規則性 (C)地球的形狀的對稱性 (D)光速的不變性 (E)光波波長的穩定性","choices":["(A)單擺的等時性","(B)地球運轉的規則性","(C)地球的形狀的對稱性","(D)光速的不變性","(E)光波波長的穩定性"],"answer":"D","explanation":"長度標準的現行定義基於光速的不變性（相對論的基本假設），使長度標準具有最高的恆常性和複製性。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-correct-statements-01', '半導體', '{"stem":"下列敘述何者正確？\n(A)二極體具有將交流電轉變成直流電的整流能力\n(B)電晶體具有放大訊號的功能\n(C)每一小晶片就是一個完整的電路，稱為積體電路\n(D)I.C.的發明使電子產品走向輕薄短小的趨勢\n(E)在半導體晶體內加入微量的雜質，會降低其導電能力","choices":["(A)二極體具有將交流電轉變成直流電的整流能力","(B)電晶體具有放大訊號的功能","(C)每一小晶片就是一個完整的電路，稱為積體電路","(D)I.C.的發明使電子產品走向輕薄短小的趨勢","(E)在半導體晶體內加入微量的雜質，會降低其導電能力"],"answer":"ABCD","explanation":"(A)正確：二極體的單向導電性可整流。(B)正確：電晶體可放大訊號。(C)正確：積體電路定義。(D)正確。(E)錯誤：摻雜微量雜質會「提高」半導體的導電能力（p型或n型半導體）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-comparison-01', '游標尺', '{"stem":"甲、乙兩人作短距離測量時，若游標尺副尺20分格等於主尺19（mm），甲測量木條長度時發現副尺之12分格與主尺之60（mm）對齊，乙測同一木條之長度時，發現副尺0刻度位於4.8cm與4.9cm之間，且副尺之6分格與主尺之60（mm）線對齊，已知甲測量值為正確。","choices":[],"answer":"見解析","explanation":"游標尺精確度=1-19/20=0.05mm\n甲：副尺12格對齊主尺60mm→副尺零點=60-12×(19/20)=60-11.4=48.6mm\n物長=48.6mm=4.860cm\n乙：副尺零在4.8~4.9cm間，副尺6格對齊→4.8cm+6×0.05mm=4.8+0.03=48.3mm\n乙讀數=48.30mm，與甲的48.6mm不同→乙測量有誤。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-faraday-generator-01', '電磁感應', '{"stem":"法拉第利用____的原理發明了交流發電機。","choices":[],"answer":"電磁感應","explanation":"法拉第利用電磁感應原理發明交流發電機——在變動磁場中導體產生感應電流。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-volume-stone-cylinder-01', '測量值與誤差', '{"stem":"將一石塊投入盛水的量筒中，如附圖所示，則石塊的體積為____cm³。","choices":[],"answer":"20.0","explanation":"排水法：石塊體積=投入後水面讀數-投入前水面讀數。根據圖中讀數差值為20.0cm³。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-structure-01', '原子模型演進', '{"stem":"下列有關原子構造的敘述，何者正確？\n(A)原子的質量均勻分佈於原子中\n(B)電子和質子的數目一定相等\n(C)質子和中子的數目一定相等\n(D)原子是很空洞的，原子核所佔據的體積很小\n(E)原子的質量集中在帶正電的原子核","choices":["(A)原子的質量均勻分佈於原子中","(B)電子和質子的數目一定相等","(C)質子和中子的數目一定相等","(D)原子是很空洞的，原子核所佔據的體積很小","(E)原子的質量集中在帶正電的原子核"],"answer":"BDE","explanation":"(A)錯誤：質量集中在原子核。\n(B)正確：中性原子中電子數=質子數。\n(C)錯誤：同位素中中子數可不同。\n(D)正確：拉塞福散射實驗證明原子核體積極小，原子大部分是空的。\n(E)正確：原子核（質子+中子）佔原子質量的99.9%以上。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-appropriate-unit-01', '長度單位', '{"stem":"要測量手邊的原子筆長度時，用下面那一個單位比較恰當\n(A)公里 (B)公尺 (C)公分 (D)公厘","choices":["(A)公里","(B)公尺","(C)公分","(D)公厘"],"answer":"C","explanation":"原子筆長度約10-15cm，用公分作單位最恰當——數值不會太大也不會太小。長度單位的選擇應使測量值在方便讀取的範圍。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-planet-orbit-01', '三角測量法', '{"stem":"設某行星及地球均在同一平面內，繞太陽運行，其軌道均為圓形，今自地球觀看行星與太陽，發現其視線的最大夾角θ=53°，則地球軌道半徑Re與行星軌道半徑R大小之比為：\n(A)5:4 (B)4:5 (C)5:3 (D)3:5 (E)4:3","choices":["(A)5:4","(B)4:5","(C)5:3","(D)3:5","(E)4:3"],"answer":"A: 5:4","explanation":"當行星與太陽的視線夾角最大時，地球到行星的連線與行星到太陽的連線垂直。\nsin53°=R/Re（行星比地球更靠近太陽的內行星情況）\n4/5=R/Re→Re:R=5:4\n\n三角測量法在天文測距中的應用。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-location-independent-01', '質量', '{"stem":"溫度保持一定之下，下列哪些物理量不隨地點而變？\n(A)密度 (B)質量 (C)重量 (D)重力加速度 (E)大氣壓力","choices":["(A)密度","(B)質量","(C)重量","(D)重力加速度","(E)大氣壓力"],"answer":"AB","explanation":"質量和密度是物質的固有屬性，不隨地點改變。重量=mg隨g變，g隨緯度和高度變，大氣壓力也隨地點變。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-39div20-02', '游標尺', '{"stem":"某游標尺最小刻度為mm，副尺20刻度的長度等於主尺39個刻度的長度。於某次量度，若副尺第11個刻度恰對正主尺11cm處，則待測物長度？\n(A)11.11cm (B)10.55cm (C)9.955cm (D)8.855cm","choices":["(A)11.11cm","(B)10.55cm","(C)9.955cm","(D)8.855cm"],"answer":"D","explanation":"副尺一格=39/20=1.95mm，精確度=0.05mm\n副尺第11格對齊主尺110mm→副尺零點=110-11×1.95=110-21.45=88.55mm=8.855cm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-painter-01', '三角測量法', '{"stem":"一畫家寫生時伸直手臂，手中持一鉛直之鉛筆，此鉛筆恰好遮住遠方一座無線電塔之視線，眼睛至鉛筆的距離為60cm，鉛筆長15cm，已知塔高75m，則畫家與塔之距離為何？\n(A)120m (B)160m (C)240m (D)300m","choices":["(A)120m","(B)160m","(C)240m","(D)300m"],"answer":"D: 300m","explanation":"三角測量法相似三角形：\n鉛筆高/眼到筆距=塔高/眼到塔距\n15/60=75/d→d=75×60/15=300m"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-fission-errors-01', '核分裂與核融合', '{"stem":"核電廠以鈾235為燃料，以慢中子促使其分裂，利用這種核分裂反應所釋出的能量來發電。有關反應事件的敘述，何者錯誤？\n(A)原子經過核分裂反應，反應前後的原子種類改變了\n(B)有的反應生成物，帶有很強的輻射性\n(C)比起煤或石油來，核燃料只以很少的質量就可產生很大的能量\n(D)這種反應生成物的輻射性，經過低溫冷處理即可清除","choices":["(A)原子經過核分裂反應，反應前後的原子種類改變了","(B)有的反應生成物，帶有很強的輻射性","(C)比起煤或石油來，核燃料只以很少的質量就可產生很大的能量","(D)這種反應生成物的輻射性，經過低溫冷處理即可清除"],"answer":"D","explanation":"(D)錯誤：核廢料的放射性無法透過低溫冷處理清除，放射性衰變是原子核的內在性質，不受溫度影響。核廢料需要長期封存等待自然衰變。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-thermodynamics-heat-energy-01', '古典物理學', '{"stem":"焦耳實驗所得的結論：熱是一種____，它可以從其它形式的能量如動能、位能、化學能、電能等轉變而來。","choices":[],"answer":"能量","explanation":"焦耳的實驗推翻「熱素說」，證明熱是一種能量形式，可由動能、位能、化學能、電能等轉變而來。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-magnitude-avogadro-01', '數量級', '{"stem":"「1莫耳」定義為0.012公斤的「碳-12」所含的原子數目，其值約為6.02×10²³，則其數量級寫為____。","choices":[],"answer":"10²⁴","explanation":"6.02×10²³中，6.02>√10≈3.16，所以數量級進一位：10²³⁺¹=10²⁴。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-river-width-01', '三角測量法', '{"stem":"如附圖所示，甲、乙兩人利用三角測量法，欲測河川的寬度，已知甲、乙兩人以彼此間的距離為基線，而與對面樹上某定點的觀測角度分別為37°與53°，若甲、乙兩人相距200公尺，則河寬為若干公尺？\n(A)64 (B)82 (C)96 (D)112 (E)48","choices":["(A)64","(B)82","(C)96","(D)112","(E)48"],"answer":"C: 96m","explanation":"設河寬h，甲到垂足d₁，乙到垂足d₂\ntan37°=h/d₁→d₁=h/tan37°=h/0.75=4h/3\ntan53°=h/d₂→d₂=h/tan53°=h/1.333=3h/4\nd₁+d₂=200→4h/3+3h/4=200→25h/12=200→h=96m\n\n三角測量法的經典應用。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-diamagnetic-01', '超導體', '{"stem":"超導體的磁浮現象，是因為超導體具有完全的____性而導致。","choices":[],"answer":"反磁","explanation":"超導體的磁浮現象（麥士納效應）源於其完全的反磁性——超導體會完全排斥外部磁場，使磁力線無法穿透，產生排斥力導致懸浮。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-diameter-01', '游標尺', '{"stem":"以游標尺測量一圓的直徑，得如下圖之結果，此圓之直徑為：\n(A)0.8釐米 (B)0.08釐米 (C)1.05釐米 (D)1.5釐米 (E)1.95釐米","choices":["(A)0.8釐米","(B)0.08釐米","(C)1.05釐米","(D)1.5釐米","(E)1.95釐米"],"answer":"C","explanation":"從圖讀取：主尺零點在1.0cm附近，游標尺副尺某格對齊主尺→1.05cm。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-gold-silver-02', '質量', '{"stem":"有一由金和銀打造而成的金屬，質量為240克，體積為15立方公分，已知金的密度為20克/立方公分，銀的密度為10克/立方公分，則金的質量____克。","choices":[],"answer":"180克","explanation":"設金質量m，銀質量240-m\nm/20+(240-m)/10=15\nm/20+24-m/10=15→-m/20=-9→m=180g"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-alloy-01', '質量', '{"stem":"密度8.9g/cm³的銅534g與密度19.3g/cm³的金772g組成的合金，其混合密度為多少g/cm³？","choices":[],"answer":"13.06 g/cm³","explanation":"銅體積=534/8.9=60cm³\n金體積=772/19.3=40cm³\n總體積=100cm³，總質量=1306g\n混合密度=1306/100=13.06 g/cm³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-maxwell-equations-01', '電磁波', '{"stem":"馬克士威方程式是將下列哪些部分以簡單、優美、嚴謹的數學組成一組方程式，構成電磁學的核心理論？\n(A)庫侖定律 (B)安培定律 (C)能量守恆定律 (D)法拉第定律 (E)磁力線的封閉性質","choices":["(A)庫侖定律","(B)安培定律","(C)能量守恆定律","(D)法拉第定律","(E)磁力線的封閉性質"],"answer":"ABDE","explanation":"馬克士威方程式由四個方程組成：(A)庫侖定律（高斯定律）、(B)安培定律（加上位移電流修正）、(D)法拉第電磁感應定律、(E)磁力線封閉性（磁場的高斯定律，無磁單極）。(C)能量守恆定律不屬於馬克士威方程式。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-volume-sand-atoms-01', '數量級', '{"stem":"如果以原子組成物質的單元，則直徑為0.1毫米的一粒細砂含有原子數目約為多少？（選最近的數量級）\n(A)10⁶ (B)10⁹ (C)10¹³ (D)10¹⁷","choices":["(A)10⁶","(B)10⁹","(C)10¹³","(D)10¹⁷"],"answer":"D","explanation":"砂粒直徑=0.1mm=10⁻⁴m，體積=(4/3)π(5×10⁻⁵)³≈5.2×10⁻¹³ m³\n原子直徑≈2×10⁻¹⁰m，體積≈(4/3)π(10⁻¹⁰)³≈4.2×10⁻³⁰ m³\n原子數≈5.2×10⁻¹³/4.2×10⁻³⁰≈1.2×10¹⁷≈10¹⁷"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-buoyancy-balance-01', '質量', '{"stem":"右圖中有一軟木球與砝碼，在等臂天平上達成平衡。若將該裝置改放在真空室內，則天平是否仍然可以維持水平的平衡狀態？","choices":[],"answer":"不能","explanation":"在空氣中平衡時，兩邊都受浮力。軟木球體積大（密度小），受的空氣浮力大；砝碼體積小（密度大），受的浮力小。移到真空中去掉浮力後，軟木球那邊會偏重（原本浮力補償了部分重量）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-fiber-advantages-02', '光纖通訊', '{"stem":"(1)通訊容量大；(2)有利於長距離通訊；(3)不受電磁干擾；(4)重量輕、體積小","choices":[],"answer":"(1)通訊容量大(2)有利於長距離通訊(3)不受電磁干擾(4)重量輕、體積小","explanation":"- 光纖通訊 — 光纖通訊的各項優點"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-history-correct-01', '光的粒子說與波動說', '{"stem":"有關光學發展的敘述何者正確？\n(A)馬克士威認為光是電磁波的一種\n(B)海更斯與牛頓對光的性質看法不同\n(C)折射定律較反射定律早發展\n(D)楊格發現光的干涉現象","choices":["(A)馬克士威認為光是電磁波的一種","(B)海更斯與牛頓對光的性質看法不同","(C)折射定律較反射定律早發展","(D)楊格發現光的干涉現象"],"answer":"ABD","explanation":"(A)正確：馬克士威預測光是電磁波。\n(B)正確：海更士主張波動說，牛頓主張粒子說。\n(C)錯誤：反射定律比折射定律更早發展。\n(D)正確：楊格的雙狹縫實驗發現光的干涉現象。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-moon-distance-01', '三角測量法', '{"stem":"將一個一元小銅板貼在窗戶的玻璃上，用一隻眼睛看它，當它剛好將滿月的月亮完全遮住時，眼睛和銅板的距離約為220公分，已知銅板直徑約為2.0公分，月球直徑為3.6×10³公里，則月球與地球的距離約為多少公里？\n(A)4.0×10³ (B)4.0×10⁵ (C)4.0×10⁷ (D)4.0×10⁹ (E)4.0×10¹¹","choices":["(A)4.0×10³","(B)4.0×10⁵","(C)4.0×10⁷","(D)4.0×10⁹","(E)4.0×10¹¹"],"answer":"B: 4.0×10⁵ km","explanation":"三角測量法相似三角形：\n銅板直徑/眼到銅板距=月球直徑/眼到月球距\n2.0/220=3.6×10³/x\nx=3.6×10³×220/2.0=3.96×10⁵≈4.0×10⁵ km"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-solar-day-angle-01', '太陽日與恆星日', '{"stem":"設行星繞太陽的軌道為圓形，此行星公轉一周費時180天，而自轉一周又20°為一太陽日，則在行星上，一太陽日為幾天？\n(A)18天 (B)17天 (C)19天 (D)10天 (E)9天","choices":["(A)18天","(B)17天","(C)19天","(D)10天","(E)9天"],"answer":"D","explanation":"一太陽日=自轉360°+公轉對應角度=360°+20°=380°（不對，重新分析）\n\n實際上：自轉一周又20°=380°為一太陽日。\n恆星日=自轉一周=360°=t天\n公轉一周=180天→每天公轉360°/180=2°/天\n\n一太陽日中，公轉角度=τ×2°，自轉角度=360°+τ×2°\n但自轉角度也=τ×(360°/t)\n\n更直接：題目說「自轉一周又20°」為一太陽日。\n設恆星日為t天，太陽日為τ天。\n自轉一周=t天，多轉20°需t×20/360=t/18天\n所以τ=t+t/18=19t/18\n\n公轉角速度=360/180=2°/天\n一太陽日公轉=τ×2°=20°→τ=10天\n恆星日t=τ×(360/380)=10×360/380≈9.47天"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-history-development-01', '光的粒子說與波動說', '{"stem":"下列有關光學發展的描述，哪一項是正確的？\n(A)反射定律比折射定律發展得早\n(B)牛頓從稜鏡色散的研究中得出白光是一種複合光的結論\n(C)海更士與牛頓對光的性質抱持相同的看法\n(D)馬克士威認為光是一種電磁波\n(E)雷射光是一種可見光","choices":["(A)反射定律比折射定律發展得早","(B)牛頓從稜鏡色散的研究中得出白光是一種複合光的結論","(C)海更士與牛頓對光的性質抱持相同的看法","(D)馬克士威認為光是一種電磁波","(E)雷射光是一種可見光"],"answer":"ABDE","explanation":"(A)正確：反射定律在古希臘就已知，折射定律（司乃耳定律）到17世紀才精確表述。\n(B)正確：牛頓用稜鏡將白光分解為彩色光譜。\n(C)錯誤：海更士主張波動說，牛頓主張粒子說，兩人觀點不同。\n(D)正確：馬克士威建立電磁理論，預測光是電磁波。\n(E)正確：雷射光屬於可見光範圍（或特定波長的電磁波）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-measurement-error-calculation-01', '測量值與誤差', '{"stem":"甲、乙、丙三人在緯度45度之海面上做重力加速度g之測量，已知最大可能值為980 cm/s²，而甲、乙、丙三人分別測得978、976、974 cm/s²。三個測量值之平均值為976 cm/s²。\n(1)試求甲的絕對誤差、相對誤差、準確度。\n(2)試求甲的絕對偏差、相對偏差、精密度。","choices":[],"answer":"見解析","explanation":"(1)絕對誤差與百分誤差：\n絕對誤差=測量值-真值=978-980=-2(cm/s²)\n相對誤差=絕對誤差/真值=-2/980=-0.00204=-0.204%\n準確度=1-|相對誤差|=1-0.00204=0.998=99.8%\n\n(2)偏差（精密度相關）：\n絕對偏差=測量值-平均值=978-976=2(cm/s²)\n相對偏差=絕對偏差/平均值=2/976=0.00205=0.205%\n精密度=1-相對偏差=1-0.00205=0.998=99.8%"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-dimension-equation-01', '因次定理', '{"stem":"假定有某個物理量x可表為x=ky+z，則\n(A)x與k的單位須相同 (B)x與y的單位須相同 (C)x與z的單位須相同 (D)x與ky的數量須相同 (E)x與z的數量須相同","choices":["(A)x與k的單位須相同","(B)x與y的單位須相同","(C)x與z的單位須相同","(D)x與ky的數量須相同","(E)x與z的數量須相同"],"answer":"C","explanation":"因次定理的因次齊一性：等號兩邊因次必須相同，加法各項因次也必須相同。因此x、ky、z三者的因次（單位）必須相同。x與z的單位須相同(C)。x與k的單位不必相同（k可能有單位使ky與x同因次）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-quantum-quark-01', '夸克理論', '{"stem":"1963年美國人蓋耳曼認為質子或中子是由3個____所組成。","choices":[],"answer":"夸克","explanation":"蓋耳曼在1963年提出夸克理論，認為質子和中子並非基本粒子，而是由三個夸克組成。夸克之間由強作用力（強核力）結合。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-triple-beam-max-01', '質量', '{"stem":"三梁天平可測定的最大值為\n(A)11.1公克 (B)111公克 (C)311公克 (D)3111公克","choices":["(A)11.1公克","(B)111公克","(C)311公克","(D)3111公克"],"answer":"C","explanation":"三梁天平三條臂分別最大為：100g+100g+100g（或200+100+10，依型號），標準型最大311g。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-measurement-error-propagation-01', '測量值與誤差', '{"stem":"量度一球，半徑誤差為2%，則\n(A)表面積誤差為若干？\n(B)體積誤差為若干？","choices":["(A)表面積誤差為若干？","(B)體積誤差為若干？"],"answer":"4%; 6%","explanation":"表面積S=4πr²，體積V=(4/3)πr³。\n誤差傳遞：若r的百分誤差為δr/r=2%\n(A)表面積∝r²，百分誤差=2×(δr/r)=2×2%=4%\n(B)體積∝r³，百分誤差=3×(δr/r)=3×2%=6%\n\n這是絕對誤差與百分誤差中誤差傳遞的基本規則：冪次函數的百分誤差=指數×原始百分誤差。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-fiber-advantages-01', '光纖通訊', '{"stem":"光纖通訊較傳統有線通訊佳的方面有哪些？\n(A)通訊容量大 (B)有利於長距離通訊 (C)不受電磁的干擾 (D)重量輕 (E)體積小","choices":["(A)通訊容量大","(B)有利於長距離通訊","(C)不受電磁的干擾","(D)重量輕","(E)體積小"],"answer":"ABCDE","explanation":"光纖通訊的五大優點全部正確：通訊容量大（頻寬高）、有利長距離傳輸（衰減小）、不受電磁干擾（光纖不導電）、重量輕、體積小。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-light-nature-01', '光的粒子說與波動說', '{"stem":"下列對於「光」的敘述，何者正確？\n(A)牛頓認為「光」的本質是「粒子」，所以「光」沿直線進行\n(B)海更士（Huygens）認為「光」的本質是「波動」，所以「光」可漫漫各處\n(C)楊格（Young）干涉實驗顯示「光」具有波動的性質\n(D)佛科（Foucault）發現「光」在水中的速率較在空氣中為慢，證實牛頓「粒子說」的預測\n(E)愛因斯坦（Einstein）認為「光」是一種「量子」，兼具「波動」和「粒子」的雙重性質，稱之為「光子」","choices":["(A)牛頓認為「光」的本質是「粒子」，所以「光」沿直線進行","(B)海更士（Huygens）認為「光」的本質是「波動」，所以「光」可漫漫各處","(C)楊格（Young）干涉實驗顯示「光」具有波動的性質","(D)佛科（Foucault）發現「光」在水中的速率較在空氣中為慢，證實牛頓「粒子說」的預測","(E)愛因斯坦（Einstein）認為「光」是一種「量子」，兼具「波動」和「粒子」的雙重性質，稱之為「光子」"],"answer":"ABCE","explanation":"(A)正確：牛頓的粒子說解釋光的直進。\n(B)正確：海更士的波動說解釋光的漫射。\n(C)正確：楊格雙狹縫干涉實驗證明光的波動性。\n(D)錯誤：佛科測得光在水中較慢，這反而推翻了牛頓粒子說（粒子說預測光在水中更快）。\n(E)正確：愛因斯坦的光量子論，光子具有光的波粒二象性。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-features-01', '超導體', '{"stem":"超導體具有下列哪些特性？\n(A)零電阻 (B)暫時電流 (C)永久電流 (D)順磁性 (E)反磁性","choices":["(A)零電阻","(B)暫時電流","(C)永久電流","(D)順磁性","(E)反磁性"],"answer":"ACE","explanation":"超導體的特性：(A)零電阻——電阻完全消失。(C)永久電流——電流可永久流動不衰減。(E)反磁性（麥士納效應）——完全排斥磁場。(B)錯：是永久電流非暫時。(D)錯：是反磁性非順磁性。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-earth-atoms-01', '質量', '{"stem":"地球質量5.98×10²⁴公斤，構成地球各種原子的平均質量為40u（1u=1.66×10⁻²⁷公斤），試估計地球上原子的數目。","choices":[],"answer":"9.00×10⁴⁹","explanation":"1個原子平均質量=40u=40×1.66×10⁻²⁷=6.64×10⁻²⁶ kg\n地球原子總數=5.98×10²⁴/6.64×10⁻²⁶≈9.00×10⁴⁹個\n數量級約為10⁵⁰。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-democritus-01', '原子模型演進', '{"stem":"最早提出原子觀念的人是\n(A)伽立略 (B)牛頓 (C)德莫克利特 (D)亞里士多德","choices":["(A)伽立略","(B)牛頓","(C)德莫克利特","(D)亞里士多德"],"answer":"C","explanation":"德莫克利特（Democritus）是古希臘哲學家，最早提出物質由不可分割的「原子」組成的觀念，是原子模型演進的起點。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-displaced-liquid-01', '質量', '{"stem":"將一石塊，放在盛滿酒精的杯中，溢出的酒精為24公克，放在盛滿某液體的杯中時，溢出的液體為27公克，設酒精的密度為0.8g/cm³，則\n(1)溢出液體的體積為？\n(2)該液體的密度為？","choices":[],"answer":"(1)30cm³ (2)0.9g/cm³","explanation":"石塊體積V=溢出酒精質量/酒精密度=24/0.8=30cm³\n溢出液體也是30cm³（同一石塊）\n液體密度=溢出液體質量/體積=27/30=0.9 g/cm³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-incorrect-01', '雷射', '{"stem":"下列有關雷射的敘述何者不正確？\n(A)雷射是受激輻射而將光增強\n(B)雷射是應用古典光學知識所做的重大發明\n(C)雷射用不同的材質製成，可發出不同顏色的光\n(D)雷射光具準直、光度強、光束不發散的特性","choices":["(A)雷射是受激輻射而將光增強","(B)雷射是應用古典光學知識所做的重大發明","(C)雷射用不同的材質製成，可發出不同顏色的光","(D)雷射光具準直、光度強、光束不發散的特性"],"answer":"B","explanation":"(B)不正確：雷射是基於量子力學的受激輻射原理，非古典光學。LASER = Light Amplification by Stimulated Emission of Radiation。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-electric-meter-01', '國際單位系統', '{"stem":"電力公司在你家所安裝的電度表，是用來測量什麼物理量？\n(A)電能 (B)電功率 (C)電流強度 (D)端電壓","choices":["(A)電能","(B)電功率","(C)電流強度","(D)端電壓"],"answer":"A","explanation":"電度表（電表）測量的是電能（單位：千瓦·小時=度）。電功率是瞬時消耗功率，電度表是累積電能的消耗。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-unit-convert-01', '有效數字', '{"stem":"若是1.23×21.44=26.3712（純數學運算）。今若有一紙條寬1.23cm，長21.44cm，則其面積為\n(1)若干cm²？\n(2)若干m²？","choices":[],"answer":"(1)26.4cm² (2)2.64×10⁻³m²","explanation":"有效數字運算法則乘法：取最少有效位數。1.23有3位，21.44有4位，取3位。\n(1)1.23×21.44=26.3712→26.4 cm²（3位有效數字）\n(2)26.4 cm²=26.4×10⁻⁴ m²=2.64×10⁻³ m²"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-ratio-mixing-01', '質量', '{"stem":"有a、b兩種液體，其密度分別為d、2d。今將兩液體混合時，混合液體的密度為6d/5。假定混合前後的體積總和不變，則a、b兩液體原來的體積整數比為？","choices":[],"answer":"4:1","explanation":"設a體積V₁，b體積V₂\n混合密度=(dV₁+2dV₂)/(V₁+V₂)=6d/5\n5(V₁+2V₂)=6(V₁+V₂)→5V₁+10V₂=6V₁+6V₂→4V₂=V₁\nV₁:V₂=4:1"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-current-definition-01', '長度標準', '{"stem":"目前所採用的長度定義，係以何種方式來標定\n(A)以手臂長度 (B)以子午線長度 (C)以鉑銥合金的標準尺 (D)利用光速為標準","choices":["(A)以手臂長度","(B)以子午線長度","(C)以鉑銥合金的標準尺","(D)利用光速為標準"],"answer":"D","explanation":"現行長度標準定義：1公尺=光在真空中行進1/299,792,458秒的距離，即利用光速的不變性來定義長度。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-particle-discovery-order-01', '原子模型演進', '{"stem":"(甲)質子 (乙)中子 (丙)電子，以上三種粒子發現的順序為：\n(A)甲乙丙 (B)甲丙乙 (C)丙乙甲 (D)丙甲乙","choices":["(A)甲乙丙","(B)甲丙乙","(C)丙乙甲","(D)丙甲乙"],"answer":"D","explanation":"電子(丙)由湯木生在1897年發現→質子(甲)由拉塞福在1919年確認→中子(乙)由查兌克在1932年發現。順序為丙甲乙。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-onnes-01', '超導體', '{"stem":"翁內斯在1911年發現汞在4.2K時，其電阻突降為零，這種電阻為零的狀態稱為\n(A)半導體 (B)超導體 (C)雷射 (D)光纖","choices":["(A)半導體","(B)超導體","(C)雷射","(D)光纖"],"answer":"B","explanation":"翁內斯在1911年發現汞（Hg）在4.2K時電阻降為零，這就是超導體現象的首次發現。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-father-of-physics-01', '物理學的發展', '{"stem":"哪一位科學家被尊稱為物理學之父？\n(A)伽利略 (B)牛頓 (C)焦耳 (D)愛因斯坦","choices":["(A)伽利略","(B)牛頓","(C)焦耳","(D)愛因斯坦"],"answer":"B","explanation":"牛頓被尊稱為物理學之父，建立了古典力學完整體系，包括運動三大定律與萬有引力定律。伽利略是實驗物理之父，焦耳主要貢獻在熱學，愛因斯坦是20世紀科學巨人。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-correct-units-01', '國際單位系統', '{"stem":"下列各物理量（）內為單位，何者正確？\n(A)熱能（卡）(B)重量（kg）(C)力（牛頓）(D)密度（kg/m³）(E)功（kg·m/s）","choices":["(A)熱能（卡）","(B)重量（kg）","(C)力（牛頓）","(D)密度（kg/m³）","(E)功（kg·m/s）"],"answer":"ACD","explanation":"(A)正確：熱能以卡為單位。(B)錯誤：重量是力，單位應為kgw或N，kg是質量單位。(C)正確：力的SI單位是牛頓。(D)正確：密度的SI單位是kg/m³。(E)錯誤：功的單位是N·m=J，非kg·m/s。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-features-01', '雷射', '{"stem":"雷射具有下列哪些特點？\n(A)準直 (B)光度強 (C)多重波長 (D)光束不發散 (E)多重頻率","choices":["(A)準直","(B)光度強","(C)多重波長","(D)光束不發散","(E)多重頻率"],"answer":"ABD","explanation":"雷射的特點：準直（方向性好）、光度強（能量集中）、光束不發散（平行光束）。雷射是單一頻率（波長），不是多重波長或多重頻率。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-archimedes-method-01', '質量', '{"stem":"傳說中古希臘科學家亞基米得在洗澡中，領悟了分辨王冠真偽的方法。這種方法主要是依據下面的那個觀念？\n(A)溫度 (B)重量 (C)密度 (D)時間","choices":["(A)溫度","(B)重量","(C)密度","(D)時間"],"answer":"C","explanation":"阿基米得利用排水法測量王冠的體積，再結合質量計算密度，與純金密度比較來判斷真偽。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-period-01', '單擺', '{"stem":"附圖為一單擺的示意圖，則擺錘由P擺至R，再由R回到P，再由P至Q位置，共歷時5秒，則此單擺之週期為____秒。","choices":[],"answer":"4","explanation":"擺錘P→R（半週期）→R→P（半週期）→P→Q（四分之一週期）=5秒\n共走了1又1/4個週期=5/4 T=5秒\n單擺週期T=5×4/5=4秒"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-length-increase-01', '單擺', '{"stem":"一單擺製成的掛鐘，其擺動為準確。若將其擺長增加20%，則此鐘每小時將\n(A)慢12分 (B)慢5.2分 (C)慢5.7分 (D)快5.2分 (E)快5.7分","choices":["(A)慢12分","(B)慢5.2分","(C)慢5.7分","(D)快5.2分","(E)快5.7分"],"answer":"B","explanation":"單擺週期T=2π√(L/g)，擺長增加20%→L''=1.2L\nT''/T=√(1.2)≈1.095\n新擺每擺一次多花9.5%的時間，即走得慢。\n真正過了60分鐘時，此鐘只走了60/1.095≈54.8分鐘，慢了60-54.8=5.2分鐘。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-not-basic-01', 'SI七大基本量', '{"stem":"下面哪一個物理量，不是國際標準單位系統的基本量\n(A)庫侖 (B)安培 (C)新燭光 (D)莫耳 (E)克氏度","choices":["(A)庫侖","(B)安培","(C)新燭光","(D)莫耳","(E)克氏度"],"answer":"A","explanation":"庫侖是電荷的單位（導出量：C=A·s），不是SI七大基本量。安培（電流）、新燭光（光強度）、莫耳（物質的量）、克氏度（溫度）都是基本量的單位。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-measurement-power-error-01', '測量值與誤差', '{"stem":"於一電路上兩點間量得其電位差為V，電位差之誤差為ΔV；電流為I，電流之誤差為ΔI，則電功率之誤差為：\n(A)ΔVΔI (B)VΔI+IΔV (C)(V-ΔV)(I-ΔI) (D)√(VIΔVΔI)","choices":["(A)ΔVΔI","(B)VΔI+IΔV","(C)","(D)√"],"answer":"B","explanation":"電功率P=VI，微分得ΔP=VΔI+IΔV（乘積的誤差傳遞公式）。\n這是絕對誤差與百分誤差中的重要公式：若z=xy，則Δz=xΔy+yΔx。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-not-20th-century-01', '半導體', '{"stem":"下面那一項發明或發現，不是這個世紀的產物\n(A)超導體 (B)水銀溫度計 (C)電晶體 (D)雷射","choices":["(A)超導體","(B)水銀溫度計","(C)電晶體","(D)雷射"],"answer":"B","explanation":"水銀溫度計由華倫海特在18世紀（1714年）發明，不是20世紀產物。超導體（1911）、電晶體（1947）、雷射（1960）都是20世紀發現/發明的。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-modern-physics-branches-01', '近代物理學', '{"stem":"下面有關物理中各學門研究內容的敘述，何者正確\n(A)原子核物理是研究原子與原子間的作用\n(B)表面物理是研究流體的行為\n(C)凝態物理是研究固態與液態的物理性質\n(D)等離子物理是研究等離子體的物理行為","choices":["(A)原子核物理是研究原子與原子間的作用","(B)表面物理是研究流體的行為","(C)凝態物理是研究固態與液態的物理性質","(D)等離子物理是研究等離子體的物理行為"],"answer":"CD","explanation":"(A)錯誤：原子核物理研究原子核內部結構與反應，非原子間作用。\n(B)錯誤：表面物理研究材料表面的物理性質，非流體。\n(C)正確：凝態物理研究固態與液態（凝聚態）。\n(D)正確：等離子物理研究等離子體（電漿）的物理行為。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-ic-features-01', '積體電路', '{"stem":"積體電路的特點為？\n(A)體積小 (B)體積大 (C)耗電量高 (D)耗電量低 (E)性能可靠","choices":["(A)體積小","(B)體積大","(C)耗電量高","(D)耗電量低","(E)性能可靠"],"answer":"ADE","explanation":"積體電路的特點是體積小、耗電量低、性能可靠。體積大和耗電量高是真空管時代的特徵。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-fiber-total-reflection-02', '光纖通訊', '{"stem":"當光的入射方向和中心軸之間的角度小於某特定角時，則光會在纖芯和包層界面處發生____，使光被限制在光纖內部傳播。","choices":[],"answer":"全反射","explanation":"光在光纖通訊中傳播時，當入射角超過臨界角（即與軸心的夾角小於某特定值），就會在纖芯與包層界面發生全反射，光被完全反射回纖芯。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-fiber-combined-01', '雷射', '{"stem":"下列何者是同時應用雷射和光纖的例子？\n(A)超市用條碼機結帳 (B)電腦光碟存取資料 (C)CD唱盤播放音樂 (D)光纖通訊系統","choices":["(A)超市用條碼機結帳","(B)電腦光碟存取資料","(C)CD唱盤播放音樂","(D)光纖通訊系統"],"answer":"D","explanation":"光纖通訊系統同時使用雷射作為光源和光纖作為傳輸介質。條碼機、光碟機、CD唱盤使用雷射但不使用光纖。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-misc-aluminum-density-01', '質量', '{"stem":"將一鋁塊投入盛水的量筒中，其水位變化如附圖所示，又將鋁塊撈起擦乾，並放置在等臂天平的左盤，當平衡時，右盤上有一個50克的砝碼，一個2克的砝碼和二個1克的砝碼，則鋁塊的密度為____g/cm³。","choices":[],"answer":"2.7","explanation":"鋁塊質量=50+2+1+1=54g\n體積=量筒水位差=20cm³（依圖）\n密度=54/20=2.7 g/cm³"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-definition-01', '質量', '{"stem":"下列關於質量的定義哪些正確？\n(A)質量是物質所含有的量\n(B)質量是由等臂天平兩端平衡時，物體與砝碼比較出來的量\n(C)質量是由外力和物質受外力後所得加速度比較出來的量\n(D)質量是物體慣性的表示","choices":["(A)質量是物質所含有的量","(B)質量是由等臂天平兩端平衡時，物體與砝碼比較出來的量","(C)質量是由外力和物質受外力後所得加速度比較出來的量","(D)質量是物體慣性的表示"],"answer":"ABCD","explanation":"質量的多重定義全部正確：\n(A)物質含量的量度\n(B)天平測量法（重力質量）\n(C)F=ma→m=F/a（慣性質量）\n(D)質量是慣性的度量"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-coulomb-inverse-01', '電磁波', '{"stem":"庫侖的靜電平方反比定律中，所謂平方反比是指\n(A)電力與電量乘積的平方成反比\n(B)電力與電量乘積的平方根成反比\n(C)電力與電荷距離的平方成反比\n(D)電力與電荷距離的平方根成反比","choices":["(A)電力與電量乘積的平方成反比","(B)電力與電量乘積的平方根成反比","(C)電力與電荷距離的平方成反比","(D)電力與電荷距離的平方根成反比"],"answer":"C","explanation":"庫侖定律 F=kq₁q₂/r²，「平方反比」指電力與兩電荷距離r的平方成反比。電力與電量乘積成正比，不是反比。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-uncertainty-01', '有效數字', '{"stem":"若是我們丈量一塊長方形的田地，由於所用的皮尺以及測量步驟的不準而得到的結果如圖，其一邊長為10.3±0.05公尺，另一邊為12.5±0.05公尺，則我們對這塊田的面積可以相信到什麼程度？（在什麼範圍以內？）試以「±」符號表示此面積的不準確度。","choices":[],"answer":"128.75±1.14(m²)","explanation":"面積A=10.3×12.5=128.75 m²\n不確定度ΔA=|10.3×0.05|+|12.5×0.05|=0.515+0.625=1.14 m²\n（乘積的誤差傳遞：ΔA=aΔb+bΔa）\n因此面積為128.75±1.14 m²"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-multi-reading-01', '螺旋測微器', '{"stem":"(1)螺旋測微器之螺距為0.5mm，套筒上刻畫50分格。於某次量度如圖所示，則待測物長度為若干？(A)6.13cm (B)6.13mm (C)6.130mm (D)6.630mm\n(2)若量測前歸零時，副尺之第47分格對正主尺中央橫線，則待測物長度為何？(A)6.770mm (B)5.560mm (C)6.160mm (D)6.100mm\n(3)本題中之螺旋測微器可以準確至何單位？(A)0.1mm (B)0.01mm (C)1μm (D)1nm","choices":["(A)6.13cm","(B)6.13mm","(C)6.130mm","(D)6.630mm","(A)6.770mm","(B)5.560mm","(C)6.160mm","(D)6.100mm","(A)0.1mm","(B)0.01mm","(C)1μm","(D)1nm"],"answer":"(1)C (2)C (3)B","explanation":"螺旋測微器每格=0.5/50=0.01mm\n(1)主尺6mm，副尺13格→6+0.13=6.130mm\n(2)零點=47格→0-3格（50-47=3）→零點=-0.03mm\n待測物=6.130-(-0.03)=6.160mm\n(3)準確到0.01mm"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-father-of-experimental-physics-01', '物理學的發展', '{"stem":"哪一位科學家被尊稱為實驗物理之父？\n(A)哥白尼 (B)克卜勒 (C)伽利略 (D)牛頓","choices":["(A)哥白尼","(B)克卜勒","(C)伽利略","(D)牛頓"],"answer":"C","explanation":"伽利略被尊稱為實驗物理之父，首創以實驗驗證假說的科學方法，透過斜面實驗發現慣性。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-scientist-matching-01', '物理學的發展', '{"stem":"下列物理理論或現象的發現者是誰？\n(1)慣性 (2)日心說 (3)萬有引力定律 (4)相對論 (5)量子論 (6)第一個發現X光的科學家 (7)行星三大運動定律 (8)光的波動說 (9)發現電子 (10)電磁感應定律","choices":[],"answer":"(1)伽利略(2)哥白尼(3)牛頓(4)愛因斯坦(5)卜朗克(6)侖琴(7)克卜勒(8)海更士(9)湯木生(10)法拉第","explanation":"此題考察物理學的發展中重要人物與貢獻的對應：\n1. 慣性→伽利略（斜面實驗）\n2. 日心說→哥白尼\n3. 萬有引力定律→牛頓\n4. 相對論→愛因斯坦\n5. 量子論→卜朗克（能量量子化）\n6. X射線→侖琴（1895年）\n7. 行星運動三大定律→克卜勒\n8. 光的粒子說與波動說中波動說→海更士\n9. 電子→湯木生（陰極射線實驗）\n10. 電磁感應→法拉第"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-correct-statements-01', '雷射', '{"stem":"下面有關雷射的敘述，何者正確\n(A)雷射光與一般光源不同，它是由高能量的粒子束所組成\n(B)雷射光的方向性很好\n(C)雷射光的強度很集中\n(D)雷射光的覆蓋面積很大","choices":["(A)雷射光與一般光源不同，它是由高能量的粒子束所組成","(B)雷射光的方向性很好","(C)雷射光的強度很集中","(D)雷射光的覆蓋面積很大"],"answer":"BC","explanation":"(A)錯誤：雷射是光（電磁波），不是粒子束。\n(B)正確：方向性好是雷射的核心特性。\n(C)正確：能量高度集中。\n(D)錯誤：雷射光束細且不發散，覆蓋面積小。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-atom-coverage-01', '長度單位', '{"stem":"大多數的原子半徑約為1埃（1Å=10⁻¹⁰m），將原子覆蓋在1平方公寸的表面所需的原子數為\n(A)10¹² (B)10¹⁴ (C)10¹⁶ (D)10¹⁸ (E)10²⁰ 個","choices":["(A)10¹²","(B)10¹⁴","(C)10¹⁶","(D)10¹⁸","(E)10²⁰ 個"],"answer":"D","explanation":"1公寸=0.1m=10⁻¹m\n1平方公寸=(10⁻¹)²=10⁻² m²\n原子直徑≈2Å=2×10⁻¹⁰m\n原子面積≈(2×10⁻¹⁰)²=4×10⁻²⁰ m²\n原子數=10⁻²/(4×10⁻²⁰)=2.5×10¹⁷≈10¹⁸"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-polarity-01', '超導體', '{"stem":"如附圖，一超導體放置在普通磁鐵的上方，因具有完全的反磁性，故懸浮於空中，則下列何者是超導體上的極性分佈？\n(A)上N下S","choices":["(A)上N下S"],"answer":"A","explanation":"超導體因完全反磁性，會在內部產生與外加磁場方向相反的磁化。若下方磁鐵上面是N極，超導體下面會感應出N極（同極相斥產生浮力），上面則是S極。因此超導體極性為上N下S（選A）。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-graph-01', '半衰期', '{"stem":"放射性物質之強度I與時間t之函數關係圖為何？","choices":[],"answer":"C","explanation":"半衰期衰變公式I=I₀(1/2)^(t/t₁/₂)，這是指數衰減函數，圖形為從I₀開始逐漸下降趨近零的曲線，但永遠不會到零。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-radiation-types-01', '放射性', '{"stem":"輻射性元素可放射出α、β、γ三種射線，其中α、β、γ射線分別為？\n(A)氫原子、電子、電磁波\n(B)氦原子核、陰極射線、電磁波\n(C)質子、電子流、能量\n(D)氦原子核、電子流、能量\n(E)氦原子核、電子流、電磁波","choices":["(A)氫原子、電子、電磁波","(B)氦原子核、陰極射線、電磁波","(C)質子、電子流、能量","(D)氦原子核、電子流、能量","(E)氦原子核、電子流、電磁波"],"answer":"BDE","explanation":"放射性三種射線：α射線=氦原子核(²He⁴)，β射線=電子流（高速電子，與陰極射線同性質），γ射線=電磁波（高能量）。\n(A)錯：α不是氫原子。(B)正確。(C)錯：α不是質子。(D)正確（能量也對）。(E)正確。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-gravitational-constant-unit-01', '國際單位系統', '{"stem":"在牛頓萬有引力定律中，兩球體間的引力可寫為F=Gm₁m₂/r²，其中m₁、m₂為質量，r為距離。若將力的單位表為牛頓時，則式中常數G的單位應寫為\n(A)牛頓·公尺/公斤 (B)牛頓·公尺²/公斤 (C)牛頓·公尺²/公斤² (D)常數是沒有單位的","choices":["(A)牛頓·公尺/公斤","(B)牛頓·公尺²/公斤","(C)牛頓·公尺²/公斤²","(D)常數是沒有單位的"],"answer":"C","explanation":"由F=Gm₁m₂/r²解出G=Fr²/(m₁m₂)\n單位：[G]=N·m²/kg²\n這是因次定理的應用——從物理公式推導常數的單位。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-basic-quantities-01', 'SI七大基本量', '{"stem":"SI單位系統中共有幾個基本量\n(A)3 (B)5 (C)7 (D)9","choices":["(A)3","(B)5","(C)7","(D)9"],"answer":"C","explanation":"國際單位系統（SI）共有SI七大基本量：長度(m)、質量(kg)、時間(s)、電流(A)、溫度(K)、物質的量(mol)、光強度(cd)。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-standard-conditions-01', '國際單位系統', '{"stem":"做為單位標準必須具有：恆常性、複製性、國際公認三個條件，則下列何者滿足上面三個條件？\n(A)以鉑銥合金標準尺作為長度的單位\n(B)以平均太陽日作為時間的單位\n(C)以¹³³Cs電磁輻射的波長作為長度單位\n(D)以鉑銥合金公斤原器作為質量單位","choices":["(A)以鉑銥合金標準尺作為長度的單位","(B)以平均太陽日作為時間的單位","(C)以¹³³Cs電磁輻射的波長作為長度單位","(D)以鉑銥合金公斤原器作為質量單位"],"answer":"D","explanation":"(A)已被取代：鉑銥合金尺會因環境變化而微變。\n(B)已被取代：平均太陽日因地球自轉減速而不恆常。\n(C)¹³³Cs是用於時間標準（非長度），且長度已改用光速定義。\n(D)正確：質量的標準仍以鉑銥合金公斤原器為基準（國際公斤原器）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-mass-decrease-01', '核分裂與核融合', '{"stem":"核分裂和核融合皆因反應後的什麼比反應前減少而釋放出巨大的核能。\n(A)總質量 (B)原子種類 (C)原子個數 (D)總能量","choices":["(A)總質量","(B)原子種類","(C)原子個數","(D)總能量"],"answer":"A","explanation":"核分裂與核融合都是因為反應後的總質量比反應前減少（質量虧損），減少的質量依E=mc²轉化為巨大能量。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-zero-error-01', '游標尺', '{"stem":"一游標尺之主尺每一刻度代表1公釐，副尺的20刻度相當於19公釐。當主尺與副尺兩端相合時，副尺的第10刻度與主尺的第9刻度相對齊。現用此游標尺測量一圓柱體的外徑，若副尺的零刻度在主尺的第11刻度及第12刻度間，而副尺的第15刻度與主尺的某刻度相對齊，則該物的外徑為\n(A)10.75 (B)11.25 (C)11.75 (D)12.25 公釐","choices":["(A)10.75","(B)11.25","(C)11.75","(D)12.25 公釐"],"answer":"D","explanation":"游標尺精確度=1-19/20=0.05mm\n零點誤差：兩端相合時第10格對齊→零點=10×0.05=0.50mm（正誤差，讀數偏大）\n或理解為：主副尺零點未對齊，副尺零點偏右0.50mm\n\n測量讀數=11+15×0.05=11+0.75=11.75mm\n外徑=11.75+0.50=12.25mm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-vernier-precision-reading-01', '游標尺', '{"stem":"(A)一游標尺的游尺20刻度間隔等於主尺的19mm，其能精確至多少mm？\n(B)設在某一量度中，游尺的零點在主尺的32、33刻度間，且游尺的第6刻度對齊主尺的某刻度的38刻度，則待測物長多少cm？","choices":["(A)一游標尺的游尺20刻度間隔等於主尺的19mm，其能精確至多少mm？","(B)設在某一量度中，游尺的零點在主尺的32、33刻度間，且游尺的第6刻度對齊主尺的某刻度的38刻度，則待測物長多少cm？"],"answer":"(A)0.05mm (B)3.230cm","explanation":"(A)游標尺精確度=主尺最小格-副尺一格=1mm-19/20mm=1/20mm=0.05mm\n(B)主尺讀數=32mm，副尺第6格對齊→6×0.05=0.30mm\n待測物=32+0.30=32.30mm=3.230cm"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-measurement-unit-01', '測量值與誤差', '{"stem":"某物長約2公尺，但某生測此物長記為20.01，則下列敘述何者錯誤？\n(A)該生所用之尺測定單位不同 (B)該生所用之尺最小刻度單位可能是公分 (C)可能看錯尺上之刻度 (D)該生所用之尺最小刻度單位可能是公寸","choices":["(A)該生所用之尺測定單位不同","(B)該生所用之尺最小刻度單位可能是公分","(C)可能看錯尺上之刻度","(D)該生所用之尺最小刻度單位可能是公寸"],"answer":"D","explanation":"記為20.01→可能是20.01公寸=2.001公尺（最小刻度0.01公寸=0.1公分）。若最小刻度是公寸（0.1m），則讀數應為20.0公寸，不會有0.01位。所以(D)最小刻度是公寸不可能。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-zhuangzi-01', '半衰期', '{"stem":"『莊子天下篇』中有言「一尺之棰，日取其半，萬世不竭」。若現在量得其長為1/256尺，則此棰從開始截取，已經過了多少天？\n接上題，若現在量得其長為0.0012尺，則此棰從開始截取，已經過了多少天？（log2=0.3010，log3=0.4771）","choices":[],"answer":"8天；9.7天","explanation":"每日取半→半衰期=1天\n(1) 1/256=(1/2)⁸→經過8天\n(2) (1/2)^n=0.0012→2^n=1/0.0012≈833.3\nn=log₂833.3=log833.3/log2=(log8.333+2)/0.3010\nlog8.333≈log(8.333)=log(25/3)=log25-log3=2log5-log3=2(1-log2)-log3=2(0.6990)-0.4771=0.9209\nn=(0.9209+2)/0.3010=2.9209/0.3010≈9.7天"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-addition-01', '有效數字', '{"stem":"某人開車行經三段路程，分別費時27.8小時、1.324小時、0.66小時，則此人開車共費時(注意有效數字的運算)\n(A)29.7840 (B)29.784 (C)29.78 (D)29.8 (E)30 小時","choices":["(A)29.7840","(B)29.784","(C)29.78","(D)29.8","(E)30 小時"],"answer":"D","explanation":"有效數字運算法則加法：結果取到最大不確定位。27.8的不確定位在小數第一位（最粗糙），因此結果也取到小數第一位。\n27.8+1.324+0.66=29.784→29.8小時"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-not-basic-02', 'SI七大基本量', '{"stem":"下面哪一個物理的單位不屬於基本單位？\n(A)公斤 (B)燭光 (C)莫耳 (D)安培 (E)庫侖","choices":["(A)公斤","(B)燭光","(C)莫耳","(D)安培","(E)庫侖"],"answer":"E","explanation":"庫侖（電荷單位）是導出單位（C=A·s），其餘公斤、燭光、莫耳、安培都是SI七大基本量的基本單位。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-volume-dam-rainfall-01', '測量值與誤差', '{"stem":"下圖為一水壩與兩座山的鉛直截面示意圖，底部是長方形凹槽代表水壩，而兩側的等腰三角形則代表山。假設山坡斜傾角θ為45度。若山區降雨量為400公厘，山高H為500公尺，水壩寬度W為100公尺且兩側山坡的雨水全部流入水壩中，則水壩的水位會因而增高多少公尺？\n(A)2 (B)4 (C)42 (D)20 (E)40","choices":["(A)2","(B)4","(C)42","(D)20","(E)40"],"answer":"B: 4m","explanation":"山坡斜角45°→山坡水平投影=500m（每側）\n兩側山坡水平面積=2×500=1000m（每單位深度）\n降雨量=400mm=0.4m\n雨水體積（每單位深度）=1000×0.4=400 m²\n\n水壩寬度=100m\n水位增高=400/100=4m"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-thermodynamics-second-law-01', '古典物理學', '{"stem":"1850年凱耳文和克勞秀士兩人說明了『熱機輸出的功一定小於輸入的熱能』，後來稱此現象為熱力學：\n(A)第零 (B)第一 (C)第二 (D)第三 (E)第四 定律","choices":["(A)第零","(B)第一","(C)第二","(D)第三","(E)第四 定律"],"answer":"C","explanation":"熱力學第二定律指出熱機無法將熱能完全轉換為功。由克勞秀士和凱耳文在1850年提出，屬於古典物理學熱學分支。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-modern-physics-scope-01', '古典物理學', '{"stem":"關於古典物理及近代物理之研究對象，下列敘述何者正確？\n(A)古典物理研究行星運動原理\n(B)古典物理研究基本粒子間之作用力\n(C)古典物理研究奈米性質\n(D)近代物理研究歐姆定律\n(E)近代物理研究光的波動性","choices":["(A)古典物理研究行星運動原理","(B)古典物理研究基本粒子間之作用力","(C)古典物理研究奈米性質","(D)近代物理研究歐姆定律","(E)近代物理研究光的波動性"],"answer":"A","explanation":"(A)正確：行星運動屬於古典物理學力學範疇。\n(B)錯誤：基本粒子屬於近代物理學。\n(C)錯誤：奈米性質屬於近代物理。\n(D)錯誤：歐姆定律屬於古典物理。\n(E)錯誤：光的波動性在古典物理中已研究。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-mass-number-01', '原子模型演進', '{"stem":"(甲)質子 (乙)中子 (丙)電子，原子的「質量數」由哪兩種粒子數決定？\n(A)甲乙 (B)甲丙 (C)乙丙 (D)以上皆可","choices":["(A)甲乙","(B)甲丙","(C)乙丙","(D)以上皆可"],"answer":"A","explanation":"原子的質量數=質子數+中子數。電子質量極小（約質子的1/1836），對質量數的貢獻可忽略。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-solar-day-relation-01', '太陽日與恆星日', '{"stem":"設恆星日週期為T₁，太陽日週期為T₂，地球繞日公轉週期為T，則三者間有何關係？","choices":[],"answer":"T/T₁-T/T₂=1","explanation":"太陽日與恆星日：在一個公轉週期T內，地球自轉T/T₁圈（恆星日計），經歷T/T₂個太陽日。因為公轉一圈額外多轉一圈，所以T/T₁ - T/T₂ = 1。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-precision-01', '螺旋測微器', '{"stem":"一螺旋測微器的螺距為1mm，而其套筒上刻有50個分度，則此測微器的準確度為？\n(A)0.02cm (B)0.2cm (C)0.002cm (D)0.01cm (E)0.001cm\n利用上題的螺旋測微器測量一待測物時，發現物長介於4與5mm間，而套筒上的讀數為30，則物長為若干mm？\n(A)4.30 (B)4.80 (C)4.60 (D)4.70 (E)4.90","choices":["(A)0.02cm","(B)0.2cm","(C)0.002cm","(D)0.01cm","(E)0.001cm\n利用上題的螺旋測微器測量一待測物時，發現物長介於4與5mm間，而套筒上的讀數為30，則物長為若干mm？","(A)4.30","(B)4.80","(C)4.60","(D)4.70","(E)4.90"],"answer":"C; C","explanation":"螺旋測微器：\n(1)每格=螺距/分度=1mm/50=0.02mm=0.002cm\n(2)物長=4mm+30×0.02mm=4+0.60=4.60mm"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-dimension-pendulum-01', '因次定理', '{"stem":"小角度擺動的單擺，具有等時性，已知其週期T與擺長L以及重力加速度g有關，若其關係可表為T=CL^a·g^b，C為無單位的係數。則：\n(1)式中的a值為何？\n(2)式中的b值為何？","choices":[],"answer":"a=1/2, b=-1/2","explanation":"因次定理：等號兩邊因次必須相同。\nT的因次=[T]，L的因次=[L]，g的因次=[LT⁻²]\n[T]=[L]^a·[LT⁻²]^b=[L^(a+b)]·[T^(-2b)]\n比較：L的指數→a+b=0，T的指數→-2b=1\n解得b=-1/2，a=1/2\n即T=C√(L/g)，這正是單擺週期公式。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-zero-error-01', '螺旋測微器', '{"stem":"一螺旋測微器其螺距為0.5mm，而套筒周緣刻劃成40個等分刻度。在未夾待測物時，把螺旋轉到底，見到螺帽邊緣在主尺之0與0.5mm之間，而第3格與主尺中央線對齊，當夾一待測物時螺帽邊緣在主尺之3.5到4mm之間，而第16格與主尺中央線對齊，求待測物長。","choices":[],"answer":"見解析","explanation":"螺旋測微器每格=0.5/40=0.0125mm\n零點讀數=0+3×0.0125=0.0375mm（正零點誤差）\n測量讀數=3.5+16×0.0125=3.5+0.2=3.7mm\n待測物長=測量讀數-零點讀數=3.7-0.0375=3.6625mm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-mixed-01', '有效數字', '{"stem":"以有效數字表示下式的答案，3.365+0.0415-2.07=1.3365，答：","choices":[],"answer":"1.34","explanation":"有效數字運算法則加減法：取最大不確定位。2.07的不確定位在小數第二位（最粗糙），結果取到小數第二位。\n3.365+0.0415-2.07=1.3365→1.34"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-ratio-mixing-02', '質量', '{"stem":"有a、b兩種液體，其密度分別為ρ₁、ρ₂。今將兩液體混合時，混合液體的密度為(ρ₁+2ρ₂)/3。假定混合前後的體積總和不變，則a、b兩液體原來的體積比為何？","choices":[],"answer":"2:1","explanation":"設V₁:V₂=x:y\n(ρ₁x+ρ₂y)/(x+y)=(ρ₁+2ρ₂)/3\n3(ρ₁x+ρ₂y)=(ρ₁+2ρ₂)(x+y)\n3ρ₁x+3ρ₂y=ρ₁x+ρ₁y+2ρ₂x+2ρ₂y\n2ρ₁x+ρ₂y=ρ₁y+2ρ₂x\n2ρ₁x-2ρ₂x=ρ₁y-ρ₂y\n2x(ρ₁-ρ₂)=y(ρ₁-ρ₂)\n2x=y→x:y=1:2... 不對\n重新：2x=y→V₁:V₂=x:y=1:2？但答案應為2:1\n\n再算：3ρ₁x+3ρ₂y=ρ₁x+2ρ₂x+ρ₁y+2ρ₂y\n(3ρ₁-ρ₁-2ρ₂)x=(ρ₁+2ρ₂-3ρ₂)y\n(2ρ₁-2ρ₂)x=(ρ₁-ρ₂)y\n2x=y... 即V₁:V₂=1:2\n但題目答案為2:1，可能a=V₁液體密度ρ₁的體積比較大。讓我重新代入驗證：V₁:V₂=2:1\n(2ρ₁+ρ₂)/3=(ρ₁+2ρ₂)/3？不等。\nV₁:V₂=1:2：(ρ₁+2ρ₂)/3=(ρ₁+2ρ₂)/3 ✓\n所以V_a:V_b=1:2，但PDF答案標2:1，可能PDF中a、b標定順序不同。依PDF記為2:1。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-dimension-flow-rate-01', '因次定理', '{"stem":"若將長度單位以L表示，質量以M表示，時間以T表示，則在單位時間通過加油槍的汽油體積，其單位應表為\n(A)ML²/T (B)L³/T (C)M/TL³ (D)M/T (E)ML³/T","choices":["(A)ML²/T","(B)L³/T","(C)M/TL³","(D)M/T","(E)ML³/T"],"answer":"B","explanation":"「單位時間通過的體積」= 體積/時間 = L³/T\n因次定理中，體積的因次是[L³]，時間的因次是[T]，因此體積流率的因次是L³/T。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-correction-01', '單擺', '{"stem":"有一單擺每日快一分鐘，其擺長應增長或縮短若干才能準確？","choices":[],"answer":"增加原長的0.0014倍","explanation":"每日快1分鐘：24小時走了24×60+1=1441分鐘（真實1440分鐘）\nT''/T=1440/1441\n單擺T∝√L→√(L''/L)=1441/1440\nL''/L=(1441/1440)²≈1+2/1440≈1.00139\n擺長應增加原長的0.0014倍"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-basic-quantity-01', 'SI七大基本量', '{"stem":"下列物理量中，何者為基本量？\n(A)時間 (B)面積 (C)密度 (D)速度","choices":["(A)時間","(B)面積","(C)密度","(D)速度"],"answer":"A","explanation":"SI七大基本量中，時間是基本量。面積（長度²）、密度（質量/體積）、速度（長度/時間）都是導出量。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-reading-01', '螺旋測微器', '{"stem":"(1)螺距0.5mm套筒區分為50刻度之螺旋測微器測一物如右圖，應該記為若干？\n(2)同(1)題之螺旋測微器今測一物如圖應讀做若干？\n(3)可知此種螺旋測微器可準確到____mm，估計到____mm。","choices":[],"answer":"(1)5.724mm (2)3.580mm (3)0.01mm; 0.001mm","explanation":"螺旋測微器讀數=主尺讀數+副尺讀數×(螺距/分格數)+估計值\n螺距0.5mm，50分格→每格=0.5/50=0.01mm\n準確到0.01mm（一個分格），估計到0.001mm（分格之間的估計）"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-foucault-01', '光的粒子說與波動說', '{"stem":"牛頓提出光的「粒子說」，預測光在水中的速度大於在真空中的速度，結果在1850年由何人測出光在水中的速度較真空中為慢？\n(A)楊格(Young) (B)菲左(Fizeau) (C)佛科(Foucault) (D)夫朗和斐(Fraunhofer) (E)海更士(Huygens)","choices":["(A)楊格","(B)菲左","(C)佛科","(D)夫朗和斐","(E)海更士"],"answer":"C","explanation":"佛科在1850年測出光在水中的速度較真空中為慢，推翻了牛頓光的粒子說與波動說中粒子說的預測（粒子說預測光在密介質中更快），支持了波動說。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-why-international-01', '國際單位系統', '{"stem":"為何國際社會有必要制定公約，採用公制單位系統？","choices":[],"answer":"見解析","explanation":"建立國際單位系統的必要性：\n1. 準確表達實驗結果\n2. 方便與他人共享實驗資料\n3. 標準制定需考慮方便性、不變性及科學根據"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-magnitude-order-02', '數量級', '{"stem":"試將下列各數以其最接近的數量級表示之。\n(A)1.21×10² (B)9.01×10⁴ (C)0.0008 (D)0.0201 (E)4.22×10¹⁸","choices":["(A)1.21×10²","(B)9.01×10⁴","(C)0.0008","(D)0.0201","(E)4.22×10¹⁸"],"answer":"10², 10⁵, 10⁻³, 10⁻², 10¹⁹","explanation":"同數量級判斷規則：\n(A)1.21<3.16→10² (B)9.01>3.16→10⁵ (C)8>3.16→10⁻³\n(D)2.01<3.16→10⁻² (E)4.22>3.16→10¹⁹"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-electrostatic-induction-01', '電磁波', '{"stem":"將一隻尺接近小紙片時，發現小紙片被尺吸引，則下面哪一種情況不可能\n(A)小紙片帶電、尺不帶電\n(B)小紙片與尺都帶電\n(C)小紙片與尺都不帶電\n(D)小紙片不帶電、尺帶電","choices":["(A)小紙片帶電、尺不帶電","(B)小紙片與尺都帶電","(C)小紙片與尺都不帶電","(D)小紙片不帶電、尺帶電"],"answer":"C","explanation":"吸引現象需要至少一方帶電：(A)可能（帶電體吸引不帶電體的感應現象）；(B)可能（異性電荷相吸）；(C)不可能（都不帶電則無靜電力）；(D)可能（尺帶電，紙片被感應）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-relativity-near-light-speed-01', '相對論', '{"stem":"下面那一個理論可說明物體運動速度在接近光速時的力學現象\n(A)庫侖平方反比定律 (B)牛頓運動定律 (C)愛因斯坦的狹義相對論 (D)司乃耳的折射定律","choices":["(A)庫侖平方反比定律","(B)牛頓運動定律","(C)愛因斯坦的狹義相對論","(D)司乃耳的折射定律"],"answer":"C","explanation":"當物體速度接近光速時，牛頓力學不再適用，必須使用愛因斯坦的狹義相對論。狹義相對論描述高速運動下的時間膨脹、長度收縮、質量增加等效應。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-refraction-application-01', '光的粒子說與波動說', '{"stem":"下面那一種現象屬於折射光學的應用\n(A)平面鏡 (B)彩虹標籤紙 (C)立體相片 (D)望遠鏡","choices":["(A)平面鏡","(B)彩虹標籤紙","(C)立體相片","(D)望遠鏡"],"answer":"D","explanation":"望遠鏡利用透鏡（折射）聚光成像，屬折射光學應用。(A)平面鏡是反射光學。(B)彩虹標籤紙利用繞射/干涉。(C)立體相片利用雙眼視差。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-fuel-01', '核分裂與核融合', '{"stem":"核能發電其原理是利用什麼物體，在控制的情況下，進行核分裂，將釋放出的核能轉變為電能。\n(A)鈾原子 (B)鈾原子核 (C)鋼原子 (D)鋼原子核","choices":["(A)鈾原子","(B)鈾原子核","(C)鋼原子","(D)鋼原子核"],"answer":"B","explanation":"核能發電是利用鈾原子核（非整個原子）進行核分裂與核融合中的核分裂反應。核分裂是原子核層級的反應，不涉及外圍電子。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-wave-theory-proposer-01', '光的粒子說與波動說', '{"stem":"最早提出光波動說的人是\n(A)愛因斯坦 (B)亞里士多德 (C)亞基米得 (D)海更士","choices":["(A)愛因斯坦","(B)亞里士多德","(C)亞基米得","(D)海更士"],"answer":"D","explanation":"海更士最早系統性地提出光的粒子說與波動說中的波動說，用波前概念解釋光的反射和折射。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-quantum-father-01', '量子論', '{"stem":"近代物理學上，被尊稱為「量子力學」之父的偉大物理學家是____。","choices":[],"answer":"卜朗克","explanation":"卜朗克在1900年提出量子論，開啟了量子力學的時代，因此被尊稱為量子力學之父。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-formula-01', '核分裂與核融合', '{"stem":"核能發電是利用____原子核在控制的情況下進行核分裂；分裂之後，若質量減少m公斤，則E=____。","choices":[],"answer":"鈾，mc²","explanation":"核能發電利用鈾（U-235）原子核在控制的連鎖反應中進行核分裂與核融合中的核分裂。根據愛因斯坦質能互換公式E=mc²，質量減少m公斤可釋放能量E=mc²。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-area-01', '有效數字', '{"stem":"欲求一長方形面積，測得其長為1.11公尺、寬為0.11公尺，則其面積為\n(A)0.1221 (B)0.122 (C)0.12 (D)0.120 平方公尺","choices":["(A)0.1221","(B)0.122","(C)0.12","(D)0.120 平方公尺"],"answer":"CD","explanation":"有效數字運算法則乘法：結果取最少有效位數。1.11有3位，0.11有2位，取2位。\n1.11×0.11=0.1221→0.12(=0.120) 平方公尺\n(C)0.12和(D)0.120都正確（0.120明確表示3位有效數字中末位零有效，但2位有效時0.12即可）。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-ic-trend-01', '積體電路', '{"stem":"哪一項發明使電子產品走向「輕、薄、短、小」的趨勢？\n(A)積體電路 (B)雷射 (C)光纖 (D)電腦","choices":["(A)積體電路","(B)雷射","(C)光纖","(D)電腦"],"answer":"A","explanation":"積體電路（IC）的發明將大量電子元件整合在微小晶片上，使電子產品體積大幅縮小。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-properties-01', '半導體', '{"stem":"下列有關「半導體」的敘述，何者正確？\n(A)可製成二極體和電晶體\n(B)導電能力介於金屬導體和絕緣體之間\n(C)數長釐米的小晶片上的電路稱為「積體電路」\n(D)積體電路的發明，使得電子產品走向「輕、薄、短小」的趨勢\n(E)數字型手錶、掌上型計算機都是由半導體元件所製成","choices":["(A)可製成二極體和電晶體","(B)導電能力介於金屬導體和絕緣體之間","(C)數長釐米的小晶片上的電路稱為「積體電路」","(D)積體電路的發明，使得電子產品走向「輕、薄、短小」的趨勢","(E)數字型手錶、掌上型計算機都是由半導體元件所製成"],"answer":"ABCDE","explanation":"所有選項都正確：\n(A)半導體是二極體與電晶體的基礎材料。\n(B)半導體導電能力介於導體與絕緣體之間。\n(C)積體電路（IC）是在小晶片上製作的完整電路。\n(D)IC使電子產品輕薄短小。\n(E)數字手錶、計算機均使用半導體元件。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-latitude-01', '單擺', '{"stem":"在日本做好的標準擺鐘，移到台灣來使用，須如何調整才能得正確時刻？\n(A)擺長增長 (B)擺長減小 (C)擺錘質量增加 (D)擺錘質量減少","choices":["(A)擺長增長","(B)擺長減小","(C)擺錘質量增加","(D)擺錘質量減少"],"answer":"B","explanation":"台灣緯度較日本低，重力加速度g較小，單擺T=2π√(L/g)，g變小→T變大→鐘走慢。要恢復正確→需減小T→減小擺長L。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-intensity-01', '半衰期', '{"stem":"一放射性元素，現在起經2年後，其強度變為原有值的1/49，則該元素現在起經3年後，其強度變為原來的若干？","choices":[],"answer":"1/343","explanation":"2年後剩1/49=(1/7)²→每年衰變為1/7\n3年後：(1/7)³=1/343\n\n（不需要求半衰期，直接用年衰變率計算）"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-wave-particle-duality-01', '光的波粒二象性', '{"stem":"光兼具哪兩種性質，前者可由光的繞射、干涉等現象，後者可由光電效應等現象，獲得佐證。\n(A)粒子、波動 (B)反射、折射 (C)折射、反射 (D)波動、粒子","choices":["(A)粒子、波動","(B)反射、折射","(C)折射、反射","(D)波動、粒子"],"answer":"D","explanation":"光的繞射、干涉證明波動性（前者），光電效應證明粒子性（後者）。注意題目問的順序是「前者...後者」，繞射干涉在前（波動），光電效應在後（粒子），因此答案是(D)波動、粒子，而非(A)。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-mixed-history-01', '電磁感應', '{"stem":"下列敘述何者正確？\n(A)法拉第認為「一封閉線圈內有磁場通過，必定產生感應電流」\n(B)楊格的雙狹縫干涉實驗證明光有波動性\n(C)伏特利用化學原理發明了電池\n(D)牛頓認為光是粒子，他預測光在水中的速度較空氣中快\n(E)將電磁現象整合成一組方程式的人是赫茲","choices":["(A)法拉第認為「一封閉線圈內有磁場通過，必定產生感應電流」","(B)楊格的雙狹縫干涉實驗證明光有波動性","(C)伏特利用化學原理發明了電池","(D)牛頓認為光是粒子，他預測光在水中的速度較空氣中快","(E)將電磁現象整合成一組方程式的人是赫茲"],"answer":"BCD","explanation":"(A)錯誤：必須是「變動的」磁場才會產生感應電流，靜止磁場不會。\n(B)正確：楊格雙狹縫干涉實驗證明光的波動性。\n(C)正確：伏打利用化學原理發明電池。\n(D)正確：牛頓的光的粒子說與波動說中粒子說預測光在水中更快（後被佛科推翻）。\n(E)錯誤：整合成方程式的是馬克士威，赫茲是實驗證實電磁波的人。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-fission-correct-01', '核分裂與核融合', '{"stem":"一般核能電廠利用鈾同位素之核分裂產生之能來發電。下列有關此核反應之敘述，何者正確？\n(A)所使用的鈾同位素為U-235\n(B)所使用的鈾同位素需受到質子的撞擊才能分裂\n(C)此核分裂反應中，反應物之質量大於生成物之質量\n(D)所使用的鈾同位素，每一莫耳分裂後所產生之能量，大約為燃燒一莫耳碳所產生熱能的一萬倍\n(E)此核分裂所放出的能量，主要來自分裂前後質子之電子組態之大幅改變","choices":["(A)所使用的鈾同位素為U-235","(B)所使用的鈾同位素需受到質子的撞擊才能分裂","(C)此核分裂反應中，反應物之質量大於生成物之質量","(D)所使用的鈾同位素，每一莫耳分裂後所產生之能量，大約為燃燒一莫耳碳所產生熱能的一萬倍","(E)此核分裂所放出的能量，主要來自分裂前後質子之電子組態之大幅改變"],"answer":"AC","explanation":"(A)正確：核電廠使用U-235。\n(B)錯誤：用慢中子撞擊，非質子。\n(C)正確：核分裂與核融合中，反應後質量減少（質量虧損轉為能量）。\n(D)錯誤：約為百萬倍，非一萬倍。\n(E)錯誤：能量來自核力（強作用力）的質量虧損，非電子組態改變。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-particle-model-limit-01', '光的粒子說與波動說', '{"stem":"對光的解釋如採用牛頓的粒子模型，則下列何者無法解釋？\n(A)光的直進 (B)光的反射 (C)光的照度 (D)光的干涉","choices":["(A)光的直進","(B)光的反射","(C)光的照度","(D)光的干涉"],"answer":"D","explanation":"牛頓的粒子模型可解釋光的直進、反射、照度（粒子數密度），但無法解釋光的干涉現象。干涉是波動特有的現象，只有光的粒子說與波動說中的波動說能解釋。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-kepler-data-01', '行星運動三大定律', '{"stem":"哪位科學家從直接觀測的天文數據中歸納出行星運動三大定律，使日心說獲得佐證？\n(A)哥白尼 (B)克卜勒 (C)伽立略 (D)牛頓","choices":["(A)哥白尼","(B)克卜勒","(C)伽立略","(D)牛頓"],"answer":"B","explanation":"克卜勒利用第谷的天文觀測數據歸納出行星運動三大定律，為日心說提供數學佐證。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-micrometer-zero-correction-01', '螺旋測微器', '{"stem":"一螺旋測微器，當螺帽轉動一周時，可推進螺柱前進一螺距設為0.5mm，且在螺帽周緣均勻刻劃50刻度。若未夾物體時旋緊套筒，螺帽第48刻度對齊主尺的中央線。當夾緊一物體時，見螺帽16刻度與主尺中央線對齊，如右圖所示。問待測物的長度為若干mm？\n(A)3.860 (B)3.680 (C)3.660 (D)3.640 (E)4.180","choices":["(A)3.860","(B)3.680","(C)3.660","(D)3.640","(E)4.180"],"answer":"B","explanation":"每格=0.5/50=0.01mm\n零點：第48格→0-2格的誤差（50-48=2格少轉）→零點=-2×0.01=-0.02mm\n讀數：主尺3.5~4mm間，第16格→3.5+16×0.01=3.66mm\n待測物=3.66-(-0.02)=3.68mm"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-faraday-discovery-01', '電磁感應', '{"stem":"何人首先發現由磁場之變動會產生電流？","choices":[],"answer":"法拉第","explanation":"法拉第在1831年發現電磁感應——變動的磁場可以產生電流，這是發電機的基本原理。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-relativity-20th-century-giant-01', '相對論', '{"stem":"哪一位科學家被尊稱為二十世紀的科學巨人？\n(A)拉塞福 (B)薛丁格 (C)愛因斯坦 (D)卜朗克","choices":["(A)拉塞福","(B)薛丁格","(C)愛因斯坦","(D)卜朗克"],"answer":"C","explanation":"愛因斯坦因提出相對論和光量子論等開創性理論，被尊稱為20世紀最偉大的科學家。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-quantum-wave-particle-duality-02', '光的波粒二象性', '{"stem":"光兼具哪兩種性質，前者可由光的繞射、干涉等現象，後者可由光電效應等現象，獲得佐證。\n(A)粒子、波動 (B)反射、折射 (C)折射、反射 (D)波動、粒子","choices":["(A)粒子、波動","(B)反射、折射","(C)折射、反射","(D)波動、粒子"],"answer":"D","explanation":"繞射、干涉（前者）佐證波動性；光電效應（後者）佐證粒子性。順序為波動在前、粒子在後，答案(D)。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-kepler-laws-01', '行星運動三大定律', '{"stem":"下列有關克卜勒的「行星運動三大定律」的敘述，何者正確？\n(A)各行星在不同的橢圓形軌道上，繞太陽公轉，太陽位於其一焦點處\n(B)行星繞太陽公轉的平均軌道半徑的平方等於近日距與遠日距的算術平均數\n(C)承(B)，等於橢圓軌跡的半長軸\n(D)地球與太陽的連線，在1月份與7月份掃過的面積不相等\n(E)行星公轉週期與半長軸的3/2次方成正比","choices":["(A)各行星在不同的橢圓形軌道上，繞太陽公轉，太陽位於其一焦點處","(B)行星繞太陽公轉的平均軌道半徑的平方等於近日距與遠日距的算術平均數","(C)承","(B)，等於橢圓軌跡的半長軸","(D)地球與太陽的連線，在1月份與7月份掃過的面積不相等","(E)行星公轉週期與半長軸的3/2次方成正比"],"answer":"ABCE","explanation":"(A)正確：第一定律（橢圓定律）。\n(B)正確：平均軌道半徑=(近日距+遠日距)/2。\n(C)正確：此平均值=半長軸。\n(D)錯誤：第二定律（等面積定律）→等時間掃過等面積，1月與7月天數相近，面積相等。\n(E)正確：第三定律 T∝a^(3/2)。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-induction-stove-01', '電磁感應', '{"stem":"家庭中常見的電磁爐，其工作原理為\n(A)運動定律 (B)反射定律 (C)電磁感應定律 (D)相對論","choices":["(A)運動定律","(B)反射定律","(C)電磁感應定律","(D)相對論"],"answer":"C","explanation":"電磁爐利用電磁感應原理：交變電流產生交變磁場，在金屬鍋底感應出渦電流，渦電流產生焦耳熱來加熱食物。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-history-01', '電磁感應', '{"stem":"下列有關在電磁學方面的敘述，何者正確？\n(A)吉爾伯特(Gilbert)發現地球磁場的存在\n(B)安培(Ampere)首先發現電和磁之間有直接的關係，而提出「安培定律」\n(C)富蘭克林(Franklin)利用單電流體理論解釋摩擦起電的現象\n(D)伏打(Volta)首先發明了電池，成為有用的直流電源\n(E)法拉第(Faraday)利用「電磁感應」的原理發明了交流發電機","choices":["(A)吉爾伯特","(B)安培","(C)富蘭克林","(D)伏打","(E)法拉第"],"answer":"ACDE","explanation":"(A)正確：吉爾伯特發現地球本身就是一個大磁鐵。\n(B)錯誤：首先發現電和磁關係的是厄司特（電流磁效應），非安培。安培定律是安培在厄司特發現之後建立的。\n(C)正確：富蘭克林用單電流體理論解釋靜電現象。\n(D)正確：伏打發明伏打電堆。\n(E)正確：法拉第發現電磁感應並發明交流發電機。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-galileo-telescope-01', '物理學的發展', '{"stem":"西元1998年11月18日凌晨一點開始，獅子座流星雨光臨地球，臺灣掀起一陣觀星熱，請問地球上第一支天文望遠鏡是由誰設計製造成功的？\n(A)托勒密(Ptolemy) (B)哥白尼(Copernicus) (C)克卜勒(Kepler) (D)伽立略(Galilei) (E)牛頓(Newton)","choices":["(A)托勒密","(B)哥白尼","(C)克卜勒","(D)伽立略","(E)牛頓"],"answer":"D","explanation":"伽利略在1609年設計製造了第一支天文望遠鏡，並用它觀測月球表面、木星衛星、金星盈虧等天體現象，為日心說提供觀測證據。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mass-inertia-01', '質量', '{"stem":"物體慣性的大小與下列何者有關？\n(A)物質含量 (B)位置 (C)溫度 (D)形狀","choices":["(A)物質含量","(B)位置","(C)溫度","(D)形狀"],"answer":"A","explanation":"物體的慣性大小由質量決定（質量越大慣性越大），與位置、溫度、形狀無關。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-fiber-total-reflection-01', '光纖通訊', '{"stem":"光纖是將純度極高的____熔融後抽絲製成，它可用於導引光的傳播方向，這是因為光在光纖內部進行____作用的緣故。","choices":[],"answer":"石英，全反射","explanation":"光纖通訊中的光纖由高純度石英（二氧化矽）製成。光在光纖內部傳播時，在纖芯與包層界面發生全反射，使光被限制在纖芯中傳輸。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-mechanics-wave-medium-01', '電磁波', '{"stem":"下列各種波在傳遞時，與介質（傳波物質）彈性的關係最密切的應是？\n(A)無線電波 (B)光波 (C)地震波 (D)雷達波","choices":["(A)無線電波","(B)光波","(C)地震波","(D)雷達波"],"answer":"C","explanation":"無線電波、光波、雷達波都是電磁波，不需介質。地震波是力學波，波速取決於介質彈性和密度。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-shadow-ratio-01', '三角測量法', '{"stem":"設太陽光在早上6時東昇，下午6時西沉，則電線桿在日光下於上午10時與下午4時，桿影長之比為何？\n(A)1:2 (B)1:3 (C)1:4 (D)2:3","choices":["(A)1:2","(B)1:3","(C)1:4","(D)2:3"],"answer":"B","explanation":"日出6:00→正午12:00→日落18:00\n上午10時：太陽角度=60°（12小時轉180°，10時對應(10-6)/12×180=60°）\n下午4時：太陽角度=120°（距正午過4小時）→實際仰角=180-120=60°？\n\n更精確：太陽從地平面到天頂的角度：\n10:00→仰角=(10-6)/(12-6)×90=60°\n16:00→仰角=(18-16)/(18-12)×90=30°\n\n影長∝1/tanθ\n比=tan30°/tan60°=(1/√3)/(√3)=1/3\n答案(B) 1:3"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-measurement-density-error-01', '測量值與誤差', '{"stem":"某生以三梁天平測得金屬小圓筒的質量為31.20g，以排水法測得此物體體積為4.00cm³，若此金屬密度為7.68g/cm³，回答下列各題：\n(1)金屬小圓筒的密度為【？】g/cm³。\n(2)此實驗之密度的絕對誤差為【？】g/cm³。\n(3)相對誤差為【？】%。","choices":[],"answer":"(1)7.8 g/cm³ (2)0.12 g/cm³ (3)1.56%","explanation":"(1)D測=M/V=31.20/4.00=7.8(g/cm³)\n(2)絕對誤差與百分誤差：|測量值-正確值|=|7.8-7.68|=0.12(g/cm³)\n(3)相對誤差=|正確值-測量值|/正確值×100%=0.12/7.68×100%=1.56%"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-solar-day-calculation-01', '太陽日與恆星日', '{"stem":"某行星繞太陽一年300天，自轉一次要50天，則其一「太陽日」為幾天？","choices":[],"answer":"60天","explanation":"公轉週期T=300天，恆星日t=50天\n太陽日與恆星日公式：太陽日=Tt/(T-t)=300×50/(300-50)=15000/250=60天"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-atomic-rutherford-scattering-01', '原子模型演進', '{"stem":"拉塞福的原子模型理論中是以α粒子來探測金箔，而α粒子所以會散射主要是受到哪種力量的作用？\n(A)萬有引力 (B)庫侖引力 (C)摩擦力 (D)庫侖斥力 (E)大氣壓力","choices":["(A)萬有引力","(B)庫侖引力","(C)摩擦力","(D)庫侖斥力","(E)大氣壓力"],"answer":"D","explanation":"拉塞福的α粒子散射實驗中，α粒子帶正電（氦核），金原子核也帶正電，同性電荷相斥，α粒子受到庫侖斥力而偏轉散射。萬有引力太弱可忽略。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-impact-01', '半導體', '{"stem":"下列哪些由物理學發展出來的技術，對二十世紀人類生活造成重大的影響？\n(A)半導體 (B)雷射 (C)光纖 (D)超導體 (E)核能","choices":["(A)半導體","(B)雷射","(C)光纖","(D)超導體","(E)核能"],"answer":"ABCDE","explanation":"半導體、雷射、光纖通訊、超導體、核能發電都是20世紀物理學發展出的重大技術，深刻改變了人類生活。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-pendulum-oscillation-count-01', '單擺', '{"stem":"當單擺做小角度的擺動時，根據實驗觀測，其擺動的週期是固定的。今有某個單擺以小角度擺動時，在1日內可擺動10⁵次，則當此擺擺動10⁸次時，須費時\n(A)10 (B)10² (C)10³ (D)10⁵ (E)10⁸-10⁵ 日","choices":["(A)10","(B)10²","(C)10³","(D)10⁵","(E)10⁸-10⁵ 日"],"answer":"C","explanation":"單擺等時性：每次擺動週期相同。\n1日=10⁵次→10⁸次=10⁸/10⁵=10³日"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-density-mixing-01', '質量', '{"stem":"密度為p₁與p₂的兩液體，且p₁大於p₂，則下列何者正確？\n(A)取等質量混合後（假定體積守恆），混合密度為(p₁+p₂)/2\n(B)取等體積混合後（假定體積守恆），混合密度為2p₁p₂/(p₁+p₂)\n(C)兩液體任意混合，密度值可以為任意數\n(D)等體積混合的密度比等質量混合的密度大","choices":["(A)取等質量混合後（假定體積守恆），混合密度為","(B)取等體積混合後（假定體積守恆），混合密度為2p₁p₂/","(C)兩液體任意混合，密度值可以為任意數","(D)等體積混合的密度比等質量混合的密度大"],"answer":"D","explanation":"等質量混合：ρ_m=2m/(m/p₁+m/p₂)=2p₁p₂/(p₁+p₂)（調和平均）\n等體積混合：ρ_v=(p₁+p₂)/2（算術平均）\n(A)錯：等質量混合是調和平均。(B)錯：等體積混合是算術平均。\n(C)錯：混合密度必在p₁和p₂之間。\n(D)正確：算術平均≥調和平均（AM-HM不等式）。"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-earth-radius-01', '三角測量法', '{"stem":"於埃及亞歷山大里亞石塔南方800km處的息尼有口深井，每當一年中夏至正午，太陽恰於頭頂，陽光可直射入井，此時亞歷山大里亞的石塔，塔尖陰影偏離鉛直線7.2°，則地球半徑約為若干公里？","choices":[],"answer":"6.4×10³ 公里","explanation":"兩地間的弧長=800km，對應的圓心角=7.2°\n地球周長=800×(360/7.2)=800×50=40000km\nR=40000/(2π)≈6366km≈6.4×10³km\n\n這是三角測量法最經典的應用——埃拉托斯特尼測量地球半徑。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-quantum-planck-01', '量子論', '{"stem":"首先提出「能量」是不連續的量，而是一束一束孤立的量（即量子）的學者是\n(A)愛因斯坦 (B)卜朗克 (C)馬士克威 (D)楊格 (E)海更士","choices":["(A)愛因斯坦","(B)卜朗克","(C)馬士克威","(D)楊格","(E)海更士"],"answer":"B","explanation":"卜朗克在1900年首先提出量子論，認為能量不是連續的，而是以量子（最小單位）的形式存在。愛因斯坦後來將量子概念應用到光（光量子），但首先提出的是卜朗克。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-astronomy-kepler-data-02', '行星運動三大定律', '{"stem":"哪一科學家從直接觀測的天文數據中歸納出行星運動三大定律，使日心說獲得佐證？\n(A)哥白尼 (B)克卜勒 (C)伽立略 (D)牛頓","choices":["(A)哥白尼","(B)克卜勒","(C)伽立略","(D)牛頓"],"answer":"B","explanation":"克卜勒從第谷數據歸納出行星運動三大定律，佐證日心說。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-semiconductor-ic-abbrev-01', '積體電路', '{"stem":"臺灣的電子工業發展蓬勃，我們的日常生活中經常提到「IC板」這個名詞，請問「IC」是什麼東西的縮寫簡稱？\n(A)微電腦 (B)積體電路 (C)二極體 (D)電晶體 (E)半導體","choices":["(A)微電腦","(B)積體電路","(C)二極體","(D)電晶體","(E)半導體"],"answer":"B","explanation":"IC是Integrated Circuit的縮寫，即積體電路。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-not-application-01', '雷射', '{"stem":"下列何者不是利用雷射的例子？\n(A)超市條碼機 (B)電腦光碟機 (C)微波爐 (D)CD唱片 (E)光纖通訊","choices":["(A)超市條碼機","(B)電腦光碟機","(C)微波爐","(D)CD唱片","(E)光纖通訊"],"answer":"C","explanation":"微波爐使用微波（電磁波）加熱，不使用雷射。(A)(B)(D)都使用雷射讀取資訊，(E)光纖通訊也使用雷射作為光源。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-superconductor-correct-01', '超導體', '{"stem":"下面有關超導體的敘述，何者正確\n(A)超導體的電阻為零\n(B)超導體的質量特別大\n(C)超導體具有反磁的特性\n(D)超導體在室溫下便可以正常工作","choices":["(A)超導體的電阻為零","(B)超導體的質量特別大","(C)超導體具有反磁的特性","(D)超導體在室溫下便可以正常工作"],"answer":"AC","explanation":"(A)正確：零電阻是超導體的核心特性。(B)錯誤：超導與質量無關。(C)正確：反磁性（麥士納效應）。(D)錯誤：目前超導體需要極低溫才能工作。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-half-life-daily-decay-01', '半衰期', '{"stem":"某放射性元素每天衰變40%，則3天後共衰變若干？\n接上題，此元素半衰期約為若干天？","choices":[],"answer":"78.4%; 1.36天","explanation":"每天剩60%→3天後剩0.6³=0.216→衰變了1-0.216=0.784=78.4%\n\n半衰期：(1/2)=(0.6)^t₁/₂\nln(0.5)=t₁/₂×ln(0.6)\nt₁/₂=ln0.5/ln0.6=0.693/0.511≈1.36天"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-optics-fizeau-speed-01', '光的粒子說與波動說', '{"stem":"物理史上第一位在地面上有限距離內，測出光速的偉大科學家是____。","choices":[],"answer":"菲左","explanation":"菲左在1849年利用齒輪法，成為第一位在地面上有限距離內成功測量光速的科學家。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-length-standard-definition-01', '長度標準', '{"stem":"依國際單位系統，長度的基本單位為公尺。一公尺的標準最初曾被定義為「由北極經巴黎到赤道的子午線（經線），其長度的一千萬分之一」。根據這個標準，問地球上的半徑約為多少公尺？","choices":[],"answer":"6.4×10⁶m","explanation":"子午線（北極到赤道）=地球周長的1/4\n1m=子午線/10⁷→子午線=10⁷m→地球周長=4×10⁷m\n周長=2πR→R=4×10⁷/(2π)=6.37×10⁶≈6.4×10⁶m\n\n這是長度標準歷史定義的應用。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-nuclear-power-principle-01', '核分裂與核融合', '{"stem":"關於核能發電，下列敘述何者正確？\n(A)核反應時損失之質量轉化成能量用以發電\n(B)收集原子核放射之電荷用以發電\n(C)核反應時，原子外圍之電子全體釋出，收集後用以發電\n(D)原子核中之質子動能加以發電\n(E)以上皆非","choices":["(A)核反應時損失之質量轉化成能量用以發電","(B)收集原子核放射之電荷用以發電","(C)核反應時，原子外圍之電子全體釋出，收集後用以發電","(D)原子核中之質子動能加以發電","(E)以上皆非"],"answer":"A","explanation":"核能發電的原理是質能互換：核分裂與核融合反應中，反應前後的質量差（質量虧損）轉化為巨大能量（E=mc²），用以加熱水產生蒸汽推動發電機。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-count-01', '有效數字', '{"stem":"下列各量中，各有多少位有效數字？\n(A)3.150cm (B)0.0315cm (C)6.025cm (D)36km (E)3.34×10⁶ (F)36.00","choices":["(A)3.150cm","(B)0.0315cm","(C)6.025cm","(D)36km","(E)3.34×10⁶"],"answer":"(A)4 (B)3 (C)4 (D)2 (E)3 (F)4","explanation":"有效數字的位數判斷規則：\n(A)3.150→末尾零有效→4位\n(B)0.0315→前導零無效→3位\n(C)6.025→中間零有效→4位\n(D)36→2位\n(E)3.34×10⁶→科學記號只看尾數→3位\n(F)36.00→末尾零有效→4位"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-triangulation-sun-image-speed-01', '三角測量法', '{"stem":"設一房屋之天花板與地板相距5m，天花板上有一小孔，問在正午時太陽經由此小孔投射在地板的像，移動的速度量值為若干公尺/秒？\n(A)π/2160 (B)π/4320 (C)π/8640 (D)π/17280 (E)π/34560","choices":["(A)π/2160","(B)π/4320","(C)π/8640","(D)π/17280","(E)π/34560"],"answer":"C","explanation":"太陽每24小時轉360°→角速度ω=2π/(24×3600) rad/s\n像的移動速度v=h×ω/2=5×2π/(2×24×3600)\n（正午太陽在天頂附近，投影移動速度≈h×dθ/dt）\nv=5×2π/(86400)=10π/86400=π/8640 m/s"}'::JSONB, 'advanced') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-volume-wood-displacement-01', '測量值與誤差', '{"stem":"小明按附圖的步驟，測量木塊的體積，試回答下列問題：\n(1)由圖(二)，你是否能測得木塊的體積？\n(2)由圖(四)、圖(五)，木塊的體積為____cm³。","choices":[],"answer":"(1)否 (2)20","explanation":"(1)木塊會浮在水面上，無法直接用排水法測量（需要用重物壓沉）。\n(2)用重物壓沉法：先測量重物在水中的體積變化，再加入木塊測量總體積變化，差值即為木塊體積=20cm³。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-significant-figures-volume-01', '有效數字', '{"stem":"把12.251cm³、20.13cm³和42.1cm³的三杯水倒入底面積為2.2cm×3.05cm的矩形柱內(注意有效數字)，則：\n(1)容器內所含水之總體積為若干？\n(2)底面積為若干？\n(3)容器內之水高為若干？","choices":[],"answer":"(1)74.5cm³ (2)6.7cm² (3)11cm","explanation":"(1)有效數字運算法則加法：結果取到最大不確定位（42.1的小數第一位）\n12.251+20.13+42.1=74.481→74.5 cm³\n\n(2)乘法：結果取最少有效位數（2.2有2位）\n2.2×3.05=6.71→6.7 cm²\n\n(3)除法：74.5/6.7=11.1→11 cm（2位有效數字）"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-electromagnetism-history-correct-01', '電磁感應', '{"stem":"下面有關電磁學的發展，何者正確\n(A)磁學的發展始於本世紀初\n(B)電磁波的發展始於19世紀\n(C)磁學的系統研究始於紀元前\n(D)電流的磁效應由奧斯特所發現","choices":["(A)磁學的發展始於本世紀初","(B)電磁波的發展始於19世紀","(C)磁學的系統研究始於紀元前","(D)電流的磁效應由奧斯特所發現"],"answer":"BD","explanation":"(A)錯誤：磁學的研究很早就開始了（古代中國的指南針）。\n(B)正確：電磁波的理論由馬克士威在19世紀提出，赫茲在19世紀末實驗證實。\n(C)錯誤：磁學的「系統」研究始於16世紀吉爾伯特，非紀元前。\n(D)正確：厄司特（奧斯特）發現電流磁效應。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-laser-properties-01', '雷射', '{"stem":"下列有關「雷射」(LASER)的敘述，何者正確？\n(A)由量子力學發展得到的重大科技\n(B)梅曼(Maiman)首先製成紅寶石雷射\n(C)雷射光的同調性極高，適合當作狹縫干涉或繞射的光源\n(D)雷射光的強度大，不適合用於醫療方面\n(E)影音光碟片是利用雷射光在其表面上標製小洞，以記錄影像聲音的數位訊號","choices":["(A)由量子力學發展得到的重大科技","(B)梅曼","(C)雷射光的同調性極高，適合當作狹縫干涉或繞射的光源","(D)雷射光的強度大，不適合用於醫療方面","(E)影音光碟片是利用雷射光在其表面上標製小洞，以記錄影像聲音的數位訊號"],"answer":"ABCE","explanation":"(A)正確：雷射原理來自量子力學的受激輻射。\n(B)正確：梅曼在1960年製成第一台紅寶石雷射。\n(C)正確：雷射的高同調性非常適合干涉實驗。\n(D)錯誤：雷射廣泛用於醫療（手術、治療等）。\n(E)正確：光碟利用雷射讀寫數位訊號。"}'::JSONB, 'intermediate') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-SI-man-made-standard-01', '質量', '{"stem":"在公制單位系統中，哪一種是唯一以人造物品作為基準的項目？\n(A)長度 (B)體積 (C)質量 (D)重量","choices":["(A)長度","(B)體積","(C)質量","(D)重量"],"answer":"C","explanation":"質量是國際單位系統中唯一仍以人造物品（鉑銥合金公斤原器）作為基準的項目。長度已改用光速定義，時間用銫原子鐘。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
INSERT INTO public.questions (id, concept_id, body, difficulty) VALUES ('Q-history-classical-physics-01', '古典物理學', '{"stem":"古典物理學是由哪些部份組成？\n(A)力學 (B)光學 (C)熱學 (D)電磁學 (E)量子力學","choices":["(A)力學","(B)光學","(C)熱學","(D)電磁學","(E)量子力學"],"answer":"ABCD","explanation":"古典物理學由力學、熱學、光學、電磁學四大分支構成。量子力學屬於近代物理學（20世紀初），因此(E)不選。"}'::JSONB, 'basic') ON CONFLICT (id) DO UPDATE SET concept_id = EXCLUDED.concept_id, body = EXCLUDED.body, difficulty = EXCLUDED.difficulty;
